INSERT INTO public.deep_cases (id, market_id, day, slot, content, tags) VALUES
($ml$a7cefbb1-3fe3-5cc1-8ef6-d4016ffe760e$ml$::uuid, $ml$healthtech$ml$, 1, 1, $ml${"id": "healthtech-d1-c1", "title": "One company, three roles", "lessonTitle": "Who's who in US healthcare", "slot": 1, "type": "apply", "brief": {"headline": "CVS Health brought in $402.1 billion in 2025. It owns an insurer, Aetna, a drug plan manager, Caremark, and the CVS Pharmacy chain.", "kicker": "Apply the map: which side of healthcare is CVS on?", "fullText": "CVS reports three businesses. Health Care Benefits, which is Aetna, brought in $143.4 billion and covered 26.6 million medical members at the end of 2025. Health Services, home of the Caremark pharmacy benefit manager, brought in $190.4 billion and processed 1.9 billion pharmacy claims. Pharmacy and Consumer Wellness, the stores, brought in $139.4 billion.\n\nThe three add up to more than the $402.1 billion total, because CVS's businesses also sell to each other. One company can be a payer, a PBM and a provider at once.", "sources": [{"url": "https://www.cvshealth.com/content/dam/enterprise/cvs-enterprise/pdfs/2026/Q4-2025-EarningsRelease.pdf", "label": "CVS Health, Q4 and full-year 2025 results"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each CVS business by its role.", "buckets": ["Payer", "PBM", "Provider"], "items": [{"text": "Aetna, which collects premiums and pays claims", "bucket": 0}, {"text": "Caremark, which runs drug plans for payers", "bucket": 1}, {"text": "CVS Pharmacy, which fills prescriptions", "bucket": 2}, {"text": "MinuteClinic-style walk-in care in a store", "bucket": 2}, {"text": "Aetna's Medicare plans, paid by the government", "bucket": 0}], "explanation": "Aetna funds care, Caremark manages drug benefits, and the pharmacy delivers care. CVS sits on all three sides."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did Health Services, the Caremark side, bring in for 2025?", "min": 0, "max": 300, "value": 190, "unit": "B", "explanation": "About $190.4 billion, the largest of the three, ahead of Aetna at $143.4 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're interviewing at CVS Health. They ask which part of healthcare the company is in.", "prompt": "Which answer shows you know the map?", "options": ["Retail, because it runs drugstores", "Insurance, because it owns Aetna", "All three: payer, PBM and provider"], "correctIndex": 2, "consequences": ["Stores brought in $139.4B of $402.1B; that misses most of it.", "Aetna is one of three businesses, not the whole company.", "You name every side and show how they connect."], "explanation": "CVS reports Aetna, Caremark and its pharmacies as separate businesses. Each sits on a different side of the money."}, "proReasoning": "Strong candidates name every side a company sits on, then say which one drives its decisions.", "commonMistake": "Calling CVS a drugstore chain. Its PBM brings in more revenue than its stores.", "mentalModel": "Name every role a company plays before you discuss it."}, "invest": {"call": {"kind": "theCall", "situation": "You add up CVS segment revenues and get far more than its $402.1 billion total.", "prompt": "What does that gap tell you?", "options": ["Money moves between its own businesses", "The company double counted its sales", "Aetna lost billions of dollars last year"], "correctIndex": 0, "consequences": ["Its units pay each other, so the parts sum above the total.", "Eliminations are standard reporting, not an error.", "The gap is internal sales, not a loss."], "explanation": "When one company is payer, PBM and pharmacy, its units trade with each other. The overlap is removed from the total."}, "proReasoning": "Investors read intersegment flows as a sign of integration. They show how much business stays inside one company.", "commonMistake": "Adding segment revenues and expecting them to match the headline total.", "mentalModel": "Large eliminations mean the parts feed each other."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup sells a tool that cuts pharmacy claim rejections. You want CVS as a customer.", "prompt": "Which CVS business should you pitch first?", "options": ["The stores, which sell household goods", "Caremark, which handles the claims", "Aetna, which sells medical coverage"], "correctIndex": 1, "consequences": ["Store retail has nothing to do with claim rejections.", "Caremark processed 1.9 billion pharmacy claims in 2025.", "Aetna pays medical claims; drug claims run through Caremark."], "explanation": "Pharmacy claims flow through the PBM. That is where a rejection tool saves the most money."}, "proReasoning": "Founders map a big company into its parts and pitch the one that owns the problem.", "commonMistake": "Pitching 'CVS' as one buyer. Each business has its own budget and problems.", "mentalModel": "Find the unit that owns the problem you solve."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says CVS is just the drugstore on the corner.", "prompt": "What's the fuller picture?", "options": ["It only runs pharmacies", "It is mainly a hospital chain", "It also owns an insurer and a PBM"], "correctIndex": 2, "consequences": ["The stores are about a third of its revenue.", "CVS reports no hospital business.", "Aetna and Caremark sit beside the stores."], "explanation": "CVS owns Aetna, an insurer, and Caremark, a pharmacy benefit manager, besides its pharmacies."}, "proReasoning": "Ask what else a familiar brand owns. In healthcare, the store is often the smallest part.", "commonMistake": "Judging a company by the part you see on the street.", "mentalModel": "One brand can be your insurer, drug plan and pharmacy."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e0207cdf1e43$ml$]::text[]),
($ml$1c1c7742-e278-5f80-828d-ecca5ed63198$ml$::uuid, $ml$healthtech$ml$, 1, 2, $ml${"id": "healthtech-d1-c2", "title": "Who pays, who gets care", "lessonTitle": "Who's who in US healthcare", "slot": 2, "type": "connect", "brief": {"headline": "In 2024 private insurance paid 31% of US health spending, Medicare 21%, Medicaid 18%, and patients 11% out of pocket.", "kicker": "Connect two ideas: payers fund care that providers deliver.", "fullText": "The US spent $5.3 trillion on health care in 2024, or $15,474 per person. Most of it was paid by payers: private insurers, Medicare and Medicaid. Patients paid 11% directly.\n\nThe money went to providers. Hospital care was the largest category at $1.63 trillion. The one who pays is rarely the one who gets the care, which is why each side has its own incentives.", "sources": [{"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Patients paid 11% of 2024 spending out of pocket.", "Medicare paid a bigger share than private insurance.", "Hospital care was the largest spending category."], "fakeIndex": 1, "explanation": "Private insurance paid 31%, more than Medicare at 21%."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand dollars per person did the US spend on health care in 2024?", "min": 0, "max": 25, "value": 15.5, "unit": "K", "explanation": "$15,474 per person, for $5.3 trillion in total."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A recruiter asks who really pays for most US health care.", "prompt": "What is the sharpest answer?", "options": ["Payers, led by private insurers", "Patients, out of their own pockets", "Hospitals, from their own budgets"], "correctIndex": 0, "consequences": ["Private insurers paid 31%, Medicare 21%, Medicaid 18%.", "Patients paid 11% directly, the smallest of the four.", "Hospitals receive money; they are not payers."], "explanation": "Payers fund most care. Patients pay a share, and providers are paid."}, "proReasoning": "Good answers give the split: private insurance, Medicare, Medicaid, then patients.", "commonMistake": "Confusing who receives money with who pays it.", "mentalModel": "Payers pay, providers get paid, patients pay a share."}, "invest": {"call": {"kind": "theCall", "situation": "You study a hospital chain. Its revenue depends on who pays for its patients.", "prompt": "What should you look at first?", "options": ["Its hospital food costs", "Its mix of private, Medicare and Medicaid", "How many beds it has across all its sites"], "correctIndex": 1, "consequences": ["Food is a small cost line.", "Payer mix sets how much each patient brings in.", "Beds show size, not what each patient pays."], "explanation": "Different payers pay different rates. The mix drives revenue."}, "proReasoning": "Investors ask who pays for a provider's patients before anything else.", "commonMistake": "Treating every patient as the same revenue.", "mentalModel": "Payer mix is revenue mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app helps patients find cheaper scans. Patients love it but rarely pay.", "prompt": "Who else could pay for it?", "options": ["Hospitals that perform the scans", "Nobody; keep it free forever", "Payers who save money on scans"], "correctIndex": 2, "consequences": ["Steering patients away cuts hospital revenue.", "Free with no buyer is not a business.", "Cheaper scans lower what insurers pay."], "explanation": "The user is the patient, but the payer saves the money. The payer can be the buyer."}, "proReasoning": "Founders follow the savings. Whoever saves money is the likely buyer.", "commonMistake": "Assuming the user must be the one who pays.", "mentalModel": "Sell to whoever saves the money."}, "curiosity": {"call": {"kind": "theCall", "situation": "You see a hospital bill and wonder who covers most of it.", "prompt": "Most likely, who pays?", "options": ["Your insurer or a government program", "You pay every dollar of it yourself", "The doctor waives it"], "correctIndex": 0, "consequences": ["Payers covered most of the $5.3 trillion in 2024.", "Patients paid 11% out of pocket on average.", "Doctors bill; they rarely waive costs."], "explanation": "Insurers, Medicare and Medicaid pay most bills. Patients pay a share."}, "proReasoning": "Look at the bill for what the insurer paid. It is usually most of it.", "commonMistake": "Thinking the price on the bill is what you will pay.", "mentalModel": "Payers carry most of the bill."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:def2444a9e2d$ml$]::text[]),
($ml$04a72c8c-cedd-5b7e-98f3-053034a062a9$ml$::uuid, $ml$healthtech$ml$, 1, 3, $ml${"id": "healthtech-d1-c3", "title": "Who buys a billing tool?", "lessonTitle": "Who's who in US healthcare", "slot": 3, "type": "decide", "brief": {"headline": "You built a tool that catches billing errors before claims go out. Hospital care is the biggest US spending category, at $1.63 trillion in 2024.", "kicker": "Decide: which side of the money do you sell to?", "fullText": "Hospitals send claims to payers and wait to be paid. An error means a denied claim, extra work and late money.\n\nPayers would rather catch errors too, but they do not send the claims. Your tool works before a claim is sent. You must pick your first buyer.", "sources": [{"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}]}, "evidence": {"kind": "faceOff", "prompt": "Who feels the pain of a claim error first?", "left": {"name": "The hospital", "note": "Sends the claim and waits to be paid"}, "right": {"name": "The insurer", "note": "Receives the claim and pays it"}, "correctIndex": 0, "explanation": "The hospital sends the claim and loses time and cash when it is denied."}, "numbers": {"kind": "numberSense", "prompt": "Hospital care was $1.63 trillion of $5.3 trillion. What share is that?", "min": 0, "max": 100, "value": 31, "unit": "%", "explanation": "About 31%. The biggest money flows through hospitals."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join the startup as its first sales hire. The founder asks where to start.", "prompt": "Which target do you propose?", "options": ["Patients paying their bills", "Hospital billing teams", "Insurance claims teams"], "correctIndex": 1, "consequences": ["Patients do not send claims.", "They send the claims and lose cash on every denial.", "Insurers receive claims after errors are made."], "explanation": "The tool works before claims go out, so the sender is the user and the buyer."}, "proReasoning": "Match the tool to whoever does the work it improves.", "commonMistake": "Picking the biggest name instead of the team with the problem.", "mentalModel": "Sell to the team that does the work."}, "invest": {"call": {"kind": "theCall", "situation": "A startup claims both hospitals and insurers will pay for its claim tool.", "prompt": "What makes you most skeptical?", "options": ["Hospitals spend $1.63 trillion", "Claims exist in every visit", "Only one side sends the claims"], "correctIndex": 2, "consequences": ["A large market is a reason to believe, not doubt.", "Volume is a strength, not a red flag.", "A tool used before sending helps the sender most."], "explanation": "A pre-send tool fits the hospital. Selling to insurers too needs a separate product."}, "proReasoning": "Investors check that the buyer actually uses the product.", "commonMistake": "Accepting a two-sided story without asking who does the work.", "mentalModel": "One product, one natural buyer first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You have money for one pilot: a hospital or an insurer.", "prompt": "Which pilot proves the most?", "options": ["A hospital, measuring fewer denials", "An insurer, measuring fewer claims", "Both at half the effort each"], "correctIndex": 0, "consequences": ["Fewer denials is a clear, countable win.", "Insurers see errors after they are made.", "Half a pilot proves nothing."], "explanation": "The hospital sends claims and can count denials before and after."}, "proReasoning": "Founders pick the pilot with the cleanest number to show.", "commonMistake": "Splitting a small budget across two buyers.", "mentalModel": "Pilot where the result is easiest to count."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why hospitals hire so many billing staff.", "prompt": "What is the main reason?", "options": ["Patients pay at the door", "Every claim must be right to get paid", "They set their own prices freely"], "correctIndex": 1, "consequences": ["Most money comes from payers, later.", "Errors mean denials and late payment.", "Payers negotiate and set many rates."], "explanation": "Hospitals are paid by payers through claims, so billing accuracy decides cash flow."}, "proReasoning": "Follow the claim: whoever sends it carries the work.", "commonMistake": "Thinking hospitals are paid when you walk out.", "mentalModel": "Claims decide when hospitals get paid."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:bf8652fc45d1$ml$]::text[]),
($ml$7f9d2e9e-3c3e-5cf8-9126-7c26b816bd4b$ml$::uuid, $ml$healthtech$ml$, 2, 1, $ml${"id": "healthtech-d2-c1", "title": "The $27,000 family plan", "lessonTitle": "How money moves in US healthcare", "slot": 1, "type": "apply", "brief": {"headline": "The average family plan through an employer cost $26,993 in 2025, up 6%. Workers paid $6,850 of it; employers paid the rest.", "kicker": "Apply the flow: where does a premium dollar come from?", "fullText": "KFF's 2025 survey of employer health benefits found family premiums averaged $26,993 a year. Workers paid $6,850 on average, about a quarter. Single coverage averaged $9,325.\n\nThe employer and worker pay the premium to an insurer, which pays the doctors and hospitals. Most workers never see the employer's share, though it comes out of what the company could pay in wages.", "sources": [{"url": "https://www.beckerspayer.com/research-analysis/employer-sponsored-family-health-coverage-reaches-27k-annually-survey/", "label": "Becker's on the KFF 2025 employer benefits survey"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Who paid most of the average 2025 family premium?", "options": ["The worker", "The insurer", "The employer"], "correctIndex": 2, "explanation": "Of $26,993, workers paid $6,850. Employers paid about $20,100."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand dollars was the employer's share of a family premium?", "min": 0, "max": 30, "value": 20, "unit": "K", "explanation": "$26,993 minus $6,850 is about $20,100."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join an HR team. A worker asks why their paycheck shows only $6,850 for health.", "prompt": "What is the clearest explanation?", "options": ["The employer pays the larger share", "Health care costs only $6,850", "The insurer covers the rest free"], "correctIndex": 0, "consequences": ["The full plan cost $26,993 in 2025.", "That is the worker share, about a quarter.", "Insurers are paid by premiums, not free."], "explanation": "Employers paid about $20,100 of the average family premium."}, "proReasoning": "Benefits staff explain the full premium, not just the paycheck line.", "commonMistake": "Letting workers think coverage costs only what they see.", "mentalModel": "Show the full premium and who pays each part."}, "invest": {"call": {"kind": "theCall", "situation": "Family premiums rose 6% in 2025 to $26,993.", "prompt": "Who feels this rise most directly?", "options": ["Drugmakers, who set list prices", "Employers, who pay most of it", "Hospitals, who receive claims"], "correctIndex": 1, "consequences": ["Drug prices feed premiums, but do not pay them.", "Employers pay about three quarters of the premium.", "Hospitals are paid by insurers, not premiums directly."], "explanation": "Employers carry most of the premium, so rising costs hit their budgets first."}, "proReasoning": "Investors watch employer costs because they drive demand for cost-cutting tools.", "commonMistake": "Forgetting that employers, not workers, pay most premiums.", "mentalModel": "Rising premiums squeeze employers first."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell a tool that lowers health costs for companies.", "prompt": "Who is your buyer?", "options": ["Each worker, one by one", "The hospitals billing the insurer", "The employer paying most of the premium"], "correctIndex": 2, "consequences": ["Workers pay a quarter and rarely buy tools.", "Hospitals earn more when costs are high.", "The employer pays about $20,100 per family plan."], "explanation": "Employers pay most of the premium and decide on benefits tools."}, "proReasoning": "Founders sell to the party with the biggest share of the bill.", "commonMistake": "Selling to workers who pay the smallest share.", "mentalModel": "Sell to whoever writes the biggest check."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your friend thinks their job pays nothing toward their health plan.", "prompt": "What's more accurate?", "options": ["The employer pays about three quarters", "The worker pays the whole premium", "The government pays it all"], "correctIndex": 0, "consequences": ["Workers paid $6,850 of $26,993 on average.", "That would be $26,993, far above the average share.", "Employer plans are funded by employers and workers."], "explanation": "On average, employers paid about $20,100 of a family plan in 2025."}, "proReasoning": "Ask HR for the full premium. It is usually about four times your share.", "commonMistake": "Thinking your paycheck deduction is the full cost.", "mentalModel": "Your job pays most of your premium."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9dc42dada935$ml$]::text[]),
($ml$3f5a1300-48e2-543c-9bdd-6bc1258a466d$ml$::uuid, $ml$healthtech$ml$, 2, 2, $ml${"id": "healthtech-d2-c2", "title": "Paid per visit", "lessonTitle": "How money moves in US healthcare", "slot": 2, "type": "connect", "brief": {"headline": "Under fee-for-service, providers are paid for each visit, test or procedure. Day 1 showed that payers, not patients, pay most of the bill.", "kicker": "Connect day 1 and day 2: payers pay, and they pay per service.", "fullText": "Day 1 showed that private insurers, Medicare and Medicaid paid most of the $5.3 trillion spent in 2024. Day 2 showed how they usually pay: fee-for-service, one payment per service.\n\nThat combination rewards doing more. The patient rarely sees the full price, the provider earns per service, and the payer covers most of it. Patients still paid $556.6 billion out of pocket in 2024.", "sources": [{"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}, {"url": "https://www.healthcare.gov/glossary/fee-for-service", "label": "HealthCare.gov, fee for service"}]}, "evidence": {"kind": "faceOff", "prompt": "Two clinics treat the same patient equally well. Who earns more under fee-for-service?", "left": {"name": "Clinic A, 10 visits", "note": "Bills each visit separately"}, "right": {"name": "Clinic B, 6 visits", "note": "Same result with fewer visits"}, "correctIndex": 0, "explanation": "Fee-for-service pays per visit. More visits mean more pay, even for the same result."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did patients pay out of pocket in 2024?", "min": 0, "max": 1000, "value": 557, "unit": "B", "explanation": "$556.6 billion, 11% of all health spending."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "In a payer analyst interview, you are asked why US costs rise so fast.", "prompt": "Which point connects day 1 and day 2?", "options": ["Doctors set prices with no limits", "Payers pay per service, so volume grows", "Patients pay most bills directly"], "correctIndex": 1, "consequences": ["Payers negotiate many rates.", "Paying per service rewards doing more.", "Patients paid 11%; payers paid most."], "explanation": "Payers fund most care and usually pay per service, which rewards volume."}, "proReasoning": "Link who pays to how they pay. That explains most cost debates.", "commonMistake": "Blaming one actor instead of the payment design.", "mentalModel": "How you pay shapes what you get."}, "invest": {"call": {"kind": "theCall", "situation": "You value a clinic chain paid mostly fee-for-service.", "prompt": "What drives its revenue most?", "options": ["How good its patient reviews are", "How few tests it orders", "How many visits and tests it bills"], "correctIndex": 2, "consequences": ["Reviews matter, but revenue follows volume.", "Fewer tests means less revenue here.", "Each service is a payment under fee-for-service."], "explanation": "Under fee-for-service, revenue rises with the number of services billed."}, "proReasoning": "Investors track visit and procedure counts for fee-for-service providers.", "commonMistake": "Valuing a provider on quality alone when it is paid on volume.", "mentalModel": "Under fee-for-service, volume is revenue."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app cuts unneeded follow-up visits. You pitch fee-for-service clinics.", "prompt": "Why might they hesitate?", "options": ["Fewer visits mean less revenue", "Patients dislike fewer visits", "Insurers ban the app"], "correctIndex": 0, "consequences": ["Each skipped visit is a lost payment for them.", "Most patients welcome fewer trips.", "Insurers usually welcome lower costs."], "explanation": "A fee-for-service clinic loses money when visits fall. Payers gain."}, "proReasoning": "Founders check whether their product cuts the buyer's revenue.", "commonMistake": "Selling savings to the party that loses from them.", "mentalModel": "Sell savings to whoever keeps them."}, "curiosity": {"call": {"kind": "theCall", "situation": "You get a separate bill for every test after one checkup.", "prompt": "Why is it billed that way?", "options": ["Tests are always free", "Providers are paid for each service", "The clinic made a billing mistake"], "correctIndex": 1, "consequences": ["Tests are services and are billed.", "Fee-for-service pays per visit, test or procedure.", "Separate lines are normal under fee-for-service."], "explanation": "Under fee-for-service, each service is billed and paid separately."}, "proReasoning": "Read each line of a bill as one paid service.", "commonMistake": "Thinking one checkup is one charge.", "mentalModel": "Each service is its own bill."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9ac68e64aca2$ml$]::text[]),
($ml$f30d8f48-a318-58d8-a4a4-6304f76d50eb$ml$::uuid, $ml$healthtech$ml$, 2, 3, $ml${"id": "healthtech-d2-c3", "title": "Denied for a coding error", "lessonTitle": "How money moves in US healthcare", "slot": 3, "type": "decide", "brief": {"headline": "You run billing for a clinic. Too many claims come back denied, and cash arrives late. Every service creates a bill and a claim.", "kicker": "Decide: where do you fix the claim flow?", "fullText": "Under fee-for-service, each visit creates a claim that the insurer must accept before paying. A wrong code or missing detail sends it back.\n\nYou can fix claims after denials, hire more staff to resubmit, or check claims before they leave. You must pick where to put your effort.", "sources": [{"url": "https://www.healthcare.gov/glossary/fee-for-service", "label": "HealthCare.gov, fee for service"}]}, "evidence": {"kind": "buildChain", "prompt": "Put a claim in order, from visit to payment.", "steps": ["The patient has a visit", "The clinic codes the services", "The claim goes to the insurer", "The insurer checks and accepts it", "The insurer pays the clinic"], "explanation": "Errors enter at coding. Catching them there prevents a denial later."}, "numbers": {"kind": "numberSense", "prompt": "How many dollars more per person did Americans spend than peer countries, in thousands?", "min": 0, "max": 10, "value": 5.7, "unit": "K", "explanation": "$5,683 more per person than comparable wealthy countries."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your manager asks how to cut denials quickly.", "prompt": "What do you propose first?", "options": ["Resubmit every denial faster", "Ask insurers to accept more errors", "Check codes before claims are sent"], "correctIndex": 2, "consequences": ["Faster rework still means late cash.", "Insurers will not accept wrong codes.", "Catching errors early stops the denial."], "explanation": "Most denials start at coding. Fixing them before sending saves rework."}, "proReasoning": "Strong billing staff fix the step where errors start.", "commonMistake": "Speeding up rework instead of preventing it.", "mentalModel": "Fix errors where they start."}, "invest": {"call": {"kind": "theCall", "situation": "A billing company says it cuts denials by checking claims before sending.", "prompt": "What would you verify?", "options": ["Denial rates before and after", "How many staff it employs", "How nice its software looks"], "correctIndex": 0, "consequences": ["A drop in denials proves the claim.", "Staff count says little about results.", "Design does not prove savings."], "explanation": "The value is fewer denials. Ask for the before and after numbers."}, "proReasoning": "Investors ask for the one number a product should move.", "commonMistake": "Judging a tool by features instead of results.", "mentalModel": "Ask for the number the product moves."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could build a denial appeals tool or a pre-send checker.", "prompt": "Which is the stronger first product?", "options": ["A patient billing chatbot", "The pre-send checker", "The appeals tool"], "correctIndex": 1, "consequences": ["Patients do not send the clinic's claims.", "Stopping errors saves the whole rework cycle.", "Appeals start after the money is already late."], "explanation": "Preventing a denial is cheaper than appealing it."}, "proReasoning": "Founders build where the problem starts, not where it ends.", "commonMistake": "Building for the cleanup instead of the cause.", "mentalModel": "Prevent before you repair."}, "curiosity": {"call": {"kind": "theCall", "situation": "A clinic tells you your claim was denied for a code error.", "prompt": "What happened?", "options": ["Your insurance plan was canceled for good", "The visit did not happen", "The service was coded wrong on the claim"], "correctIndex": 2, "consequences": ["Coding errors are not cancellations.", "The claim exists; its code was wrong.", "A wrong code sends a claim back."], "explanation": "Claims carry codes for each service. A wrong one gets the claim denied."}, "proReasoning": "Ask the clinic to fix and resend. Many denials are simple errors.", "commonMistake": "Assuming a denial means you are not covered.", "mentalModel": "Many denials are fixable errors."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4ff7cb13234c$ml$]::text[]),
($ml$f20a3a1c-b030-5bcf-a805-67793abd02a4$ml$::uuid, $ml$healthtech$ml$, 3, 1, $ml${"id": "healthtech-d3-c1", "title": "A state tries to split PBMs", "lessonTitle": "Who holds the power in healthcare", "slot": 1, "type": "apply", "brief": {"headline": "Arkansas passed Act 624 to bar pharmacy benefit managers from owning pharmacies in the state. A federal judge blocked it on July 28, 2025.", "kicker": "Apply the power map: what happens when a state takes on PBMs?", "fullText": "Act 624 would have forced vertically integrated PBMs to sell or close their Arkansas pharmacies. Express Scripts and other PBMs sued.\n\nJudge Brian Miller granted a preliminary injunction. He found the law likely discriminates against out-of-state companies and likely conflicts with TRICARE, the military health program. He rejected several other claims. Arkansas appealed on July 31, 2025.", "sources": [{"url": "https://www.mintz.com/insights-center/viewpoints/2146/2025-08-06-federal-court-blocks-arkansas-pbm-ownership-law-citing", "label": "Mintz, court blocks Arkansas PBM ownership law"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Act 624 barred PBMs from owning pharmacies in Arkansas.", "The judge found the law fully constitutional.", "Arkansas appealed the ruling in July 2025."], "fakeIndex": 1, "explanation": "The judge blocked the law, finding it likely breaks the Commerce Clause and conflicts with TRICARE."}, "numbers": {"kind": "numberSense", "prompt": "What share of US prescriptions do the three biggest PBMs process?", "min": 0, "max": 100, "value": 80, "unit": "%", "explanation": "Nearly 80%: OptumRx, Express Scripts and Caremark.", "sources": ["ftc_pbm"]}, "calls": {"career": {"call": {"kind": "theCall", "situation": "At a policy internship, you are asked why Arkansas targeted PBM pharmacies.", "prompt": "What is the core concern?", "options": ["PBMs make the drugs that pharmacies sell", "PBMs can steer patients to their own stores", "PBMs charge pharmacists rent"], "correctIndex": 1, "consequences": ["Drugmakers make drugs; PBMs manage plans.", "The FTC flagged steering by integrated PBMs.", "PBMs set reimbursement, not rent."], "explanation": "A PBM that owns pharmacies can send patients to them. That squeezes independents."}, "proReasoning": "Name the conflict of interest before the law that targets it.", "commonMistake": "Describing the law without the incentive behind it.", "mentalModel": "Name the incentive a rule is aimed at."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in an integrated PBM owner. More states propose laws like Act 624.", "prompt": "How should you read the Arkansas ruling?", "options": ["A final win for PBMs everywhere", "Proof the laws will pass", "A pause, with appeals still open"], "correctIndex": 2, "consequences": ["One district ruling does not bind every state.", "The law was blocked, not upheld.", "A preliminary injunction is not the final word."], "explanation": "The injunction halts the law for now. Arkansas appealed, and other states may try again."}, "proReasoning": "Investors treat early rulings as risk reduced, not removed.", "commonMistake": "Treating a preliminary injunction as the end of the fight.", "mentalModel": "Early rulings lower risk; they rarely end it."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software for independent pharmacies facing PBM pressure.", "prompt": "What does the ruling mean for your market?", "options": ["Their squeeze continues, so demand stays", "Independents no longer need any outside help", "PBMs must now buy your tool"], "correctIndex": 0, "consequences": ["With the law blocked, the pressure remains.", "The ruling kept the status quo in place.", "No ruling requires PBMs to buy anything."], "explanation": "The law would have reshaped the market. Blocked, the independents' problems remain."}, "proReasoning": "Founders read rulings for what stays the same as much as what changes.", "commonMistake": "Waiting for a law to solve your customers' problem.", "mentalModel": "Build for the problem that persists."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear a judge stopped a law against PBM-owned pharmacies.", "prompt": "Why did the judge stop it?", "options": ["Pharmacists asked to keep PBMs", "It likely hurt out-of-state firms unfairly", "PBMs proved they lower drug prices for all"], "correctIndex": 1, "consequences": ["The suit was brought by PBMs.", "The judge cited the Commerce Clause.", "The ruling did not turn on prices."], "explanation": "The judge found the law likely discriminates against out-of-state companies and conflicts with TRICARE."}, "proReasoning": "Read why a law was blocked. It is often about who has the power to make it.", "commonMistake": "Assuming a blocked law was a bad idea on the merits.", "mentalModel": "Courts often rule on power, not merits."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:932753b91133$ml$]::text[]),
($ml$11ef22aa-c676-5917-9b5a-78bd73267f82$ml$::uuid, $ml$healthtech$ml$, 3, 2, $ml${"id": "healthtech-d3-c2", "title": "Payer and PBM under one roof", "lessonTitle": "Who holds the power in healthcare", "slot": 2, "type": "connect", "brief": {"headline": "UnitedHealth Group brought in $447.6 billion in 2025. It owns UnitedHealthcare, an insurer, and OptumRx, one of the three largest PBMs.", "kicker": "Connect day 1 and day 3: one company, more than one role.", "fullText": "Day 1 split healthcare into payers, providers and pharma with its middlemen. Day 3 showed that the biggest PBMs are owned by the biggest insurers.\n\nUnitedHealth's revenue grew 12% in 2025. Its insurer and its PBM sit side by side, just as CVS owns Aetna and Caremark. When the payer and the PBM share an owner, the roles from day 1 blur.", "sources": [{"url": "https://www.unitedhealthgroup.com/newsroom/2026/2026-01-27-uhg-reports-2025-results-and-issues-2026-outlook.html", "label": "UnitedHealth Group 2025 results"}, {"url": "https://www.arnoldporter.com/en/perspectives/advisories/2024/07/ftc-interim-staff-report-on-prescription-drug-middlemen", "label": "Arnold & Porter on the FTC PBM report"}, {"url": "https://www.cvshealth.com/content/dam/enterprise/cvs-enterprise/pdfs/2026/Q4-2025-EarningsRelease.pdf", "label": "CVS Health, Q4 and full-year 2025 results"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each business by its role.", "buckets": ["Payer", "PBM"], "items": [{"text": "UnitedHealthcare", "bucket": 0}, {"text": "OptumRx", "bucket": 1}, {"text": "Aetna", "bucket": 0}, {"text": "Caremark", "bucket": 1}, {"text": "Express Scripts", "bucket": 1}], "explanation": "UnitedHealthcare and Aetna are insurers. OptumRx, Caremark and Express Scripts are the three largest PBMs."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did UnitedHealth Group bring in for 2025?", "min": 0, "max": 600, "value": 448, "unit": "B", "explanation": "$447.6 billion, up 12% from 2024."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You're asked in an Optum interview how it relates to UnitedHealthcare.", "prompt": "What is the best framing?", "options": ["Rival companies in the same city", "A supplier with no shared owner", "Sister businesses under one owner"], "correctIndex": 2, "consequences": ["They share a parent; they do not compete.", "Optum and UnitedHealthcare share an owner.", "Both sit inside UnitedHealth Group."], "explanation": "UnitedHealth owns both the insurer and Optum, which includes OptumRx."}, "proReasoning": "Ask who owns whom before you discuss strategy.", "commonMistake": "Treating Optum as an outside vendor.", "mentalModel": "Ownership explains strategy."}, "invest": {"call": {"kind": "theCall", "situation": "You compare UnitedHealth and CVS. Both own an insurer and a PBM.", "prompt": "What shared risk should you weigh?", "options": ["Regulators targeting integration", "Falling demand for prescriptions", "Too few patients overall"], "correctIndex": 0, "consequences": ["The FTC studied integrated PBMs closely.", "Prescriptions keep growing.", "Both serve tens of millions of people."], "explanation": "Owning the payer and the PBM drives revenue and draws regulators."}, "proReasoning": "Investors price in rule changes aimed at a business model.", "commonMistake": "Counting the gains of integration and not its legal risk.", "mentalModel": "Integration is both strategy and risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your drug pricing tool sells to employers. Many already use an insurer-owned PBM.", "prompt": "What pitch fits best?", "options": ["A cheaper insurance plan", "Independent checks on what the PBM charges", "Replace the insurer with your own product"], "correctIndex": 1, "consequences": ["You sell a tool, not a plan.", "Employers want someone checking the middleman.", "Replacing an insurer is a different business."], "explanation": "When the payer and PBM share an owner, employers value an outside view."}, "proReasoning": "Founders sell transparency where incentives are tangled.", "commonMistake": "Competing head-on with a giant instead of serving its customers.", "mentalModel": "Sell the outside view."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your insurance card and your drug plan show different names.", "prompt": "How can they still be one company?", "options": ["They are always unrelated", "Your employer owns them", "A parent owns both brands"], "correctIndex": 2, "consequences": ["Many pairs share a parent.", "Employers buy plans; they do not own them.", "UnitedHealth owns UnitedHealthcare and OptumRx."], "explanation": "Big health companies run several brands, like an insurer and a PBM."}, "proReasoning": "Look up the parent company behind each name on your card.", "commonMistake": "Assuming different brand names mean different owners.", "mentalModel": "Different names can share one owner."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5d8edabbe4d3$ml$]::text[]),
($ml$bee5dbe3-3cff-5274-8175-39cee04d9b91$ml$::uuid, $ml$healthtech$ml$, 3, 3, $ml${"id": "healthtech-d3-c3", "title": "Choosing a drug plan manager", "lessonTitle": "Who holds the power in healthcare", "slot": 3, "type": "decide", "brief": {"headline": "You run benefits for a 2,000-person company. Your insurer offers its own PBM. The FTC notes that insurer-owned PBMs can steer patients to their own pharmacies.", "kicker": "Decide: what do you ask before signing?", "fullText": "The top six PBMs handle more than 90% of US prescriptions. The biggest are owned by the biggest insurers, and many also own specialty and retail pharmacies.\n\nYou can accept the bundle or test the terms first. Your choice affects what your workers pay and where they fill prescriptions.", "sources": [{"url": "https://www.arnoldporter.com/en/perspectives/advisories/2024/07/ftc-interim-staff-report-on-prescription-drug-middlemen", "label": "Arnold & Porter on the FTC PBM report"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What should you ask an insurer-owned PBM first?", "options": ["Whether it steers patients to its pharmacies", "How many years it has been in the business", "Whether its website has an app"], "correctIndex": 0, "explanation": "Steering to owned pharmacies is the conflict the FTC flagged. It affects your costs and workers' choices."}, "numbers": {"kind": "numberSense", "prompt": "What share of US prescriptions do the top six PBMs handle?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "More than 90%. Few alternatives exist outside the biggest six."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for one rule to judge PBM bids.", "prompt": "Which do you propose?", "options": ["Compare net cost and pharmacy rules", "Pick the most famous name", "Pick the lowest list price on offer"], "correctIndex": 0, "consequences": ["Net cost and steering decide real value.", "Fame does not show terms.", "List prices hide rebates and fees."], "explanation": "Judge a PBM by what you really pay and where workers must fill prescriptions."}, "proReasoning": "Benefits pros compare terms, not brands.", "commonMistake": "Choosing on reputation alone.", "mentalModel": "Compare terms, not names."}, "invest": {"call": {"kind": "theCall", "situation": "Employers keep picking insurer-owned PBMs for convenience.", "prompt": "What does that mean for the integrated giants?", "options": ["No effect on revenue", "Sticky revenue, with regulatory risk", "A business that is shrinking fast"], "correctIndex": 1, "consequences": ["Bundles add revenue to each owner.", "Bundles keep customers, but draw scrutiny.", "Bundled buying keeps them growing."], "explanation": "Bundling keeps employers inside one company, which the FTC is studying."}, "proReasoning": "Investors weigh stickiness against the chance rules force a split.", "commonMistake": "Ignoring the rules risk in a strong business.", "mentalModel": "Sticky revenue can still be fragile."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could help employers audit PBM contracts.", "prompt": "Who feels the most pain?", "options": ["The largest PBMs", "Patients picking a pharmacy near home", "Mid-size employers with no PBM experts"], "correctIndex": 2, "consequences": ["PBMs write the contracts.", "Patients rarely see the contract.", "They sign complex contracts with little help."], "explanation": "Mid-size employers sign PBM deals without in-house experts."}, "proReasoning": "Founders look for buyers who sign big contracts alone.", "commonMistake": "Selling to the party that writes the contract.", "mentalModel": "Help whoever signs without help."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your drug plan pushes you to use one pharmacy chain.", "prompt": "Why might that be?", "options": ["Your PBM may own that chain", "That chain is always cheapest", "A law requires it"], "correctIndex": 0, "consequences": ["Insurer-owned PBMs can steer to their pharmacies.", "Price is not the only reason for steering.", "No law picks your pharmacy chain."], "explanation": "Some PBMs own pharmacies and steer patients to them."}, "proReasoning": "Ask whether your PBM owns the pharmacy it recommends.", "commonMistake": "Assuming the suggested pharmacy is the cheapest one.", "mentalModel": "Recommendations can follow ownership."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e77499ce5d3c$ml$]::text[]),
($ml$7b40ab83-c1c6-5b2e-8d8a-cbe1724cf14a$ml$::uuid, $ml$healthtech$ml$, 4, 1, $ml${"id": "healthtech-d4-c1", "title": "A fifth of the economy by 2033", "lessonTitle": "The numbers that define US healthcare", "slot": 1, "type": "apply", "brief": {"headline": "CMS projects US health spending will reach $8.6 trillion by 2033, or 20.3% of GDP, up from 17.6% in 2023.", "kicker": "Apply the numbers: how fast is health spending growing?", "fullText": "CMS expects national health spending to grow 5.8% a year on average from 2024 to 2033. The whole economy is expected to grow 4.3% a year.\n\nWhen one part grows faster than the whole, its share rises.", "sources": [{"url": "https://www.beckershospitalreview.com/finance/us-to-spend-8-6-trillion-on-healthcare-by-2033-cms/", "label": "Becker's, US to spend $8.6 trillion on health care by 2033"}]}, "evidence": {"kind": "faceOff", "prompt": "Which grows faster from 2024 to 2033, by CMS projections?", "left": {"name": "Health spending", "note": "Projected 5.8% a year"}, "right": {"name": "The whole economy", "note": "Projected 4.3% a year"}, "correctIndex": 0, "explanation": "Health spending outgrows GDP, so its share rises from 17.6% to 20.3%."}, "numbers": {"kind": "numberSense", "prompt": "What share of GDP does CMS project for health spending in 2033?", "min": 0, "max": 30, "value": 20.3, "unit": "%", "explanation": "20.3%, about one dollar in five."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "An interviewer asks why health care keeps taking more of the economy.", "prompt": "What is the cleanest answer?", "options": ["The economy is shrinking", "More people work in hospitals", "It grows faster than GDP every year"], "correctIndex": 2, "consequences": ["GDP is projected to grow 4.3% a year.", "Jobs follow spending; they do not explain it.", "5.8% against 4.3% raises its share."], "explanation": "When spending grows faster than the economy, its share of GDP rises."}, "proReasoning": "Explain shares with growth rates, not anecdotes.", "commonMistake": "Confusing a rising share with a shrinking economy.", "mentalModel": "Faster growth, bigger share."}, "invest": {"call": {"kind": "theCall", "situation": "You compare health care with the wider economy for a long-term portfolio.", "prompt": "What do the projections suggest?", "options": ["Health care keeps growing its share", "Health care growth stops by 2026", "Health care will shrink as a share"], "correctIndex": 0, "consequences": ["CMS projects 20.3% of GDP by 2033.", "CMS projects growth each year to 2033.", "The share rises, from 17.6% to 20.3%."], "explanation": "Spending is projected to grow faster than GDP through 2033."}, "proReasoning": "Investors use long projections as a tailwind, not a guarantee.", "commonMistake": "Treating a projection as a promise.", "mentalModel": "Projections are tailwinds, not guarantees."}, "build_startup": {"call": {"kind": "theCall", "situation": "You pitch a cost-saving tool to a hospital CFO.", "prompt": "Which fact frames your pitch best?", "options": ["Costs are about to fall", "Costs grow faster than the economy", "Health care is a small sector"], "correctIndex": 1, "consequences": ["CMS projects steady growth.", "Rising costs keep buyers looking for savings.", "It is near a fifth of GDP."], "explanation": "Spending outgrows GDP, so payers and providers keep hunting for savings."}, "proReasoning": "Founders open with the pressure their buyer already feels.", "commonMistake": "Leading with features before the cost pressure.", "mentalModel": "Start with the pressure the buyer feels."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that health care could reach a fifth of the economy.", "prompt": "Why is that happening?", "options": ["Fewer people use health care each year", "Prices are frozen by law", "Spending grows faster than the economy"], "correctIndex": 2, "consequences": ["Use and spending are both rising.", "No law freezes most prices.", "5.8% versus 4.3% a year."], "explanation": "Health spending is projected to grow 5.8% a year, faster than the economy."}, "proReasoning": "Compare two growth rates to see where shares are heading.", "commonMistake": "Thinking a bigger share means the economy is shrinking.", "mentalModel": "Compare growth rates to see shares change."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0c77d87daa52$ml$]::text[]),
($ml$d47bba52-f63b-53cb-ad49-2abccb1e3b42$ml$::uuid, $ml$healthtech$ml$, 4, 2, $ml${"id": "healthtech-d4-c2", "title": "Volume meets the biggest bill", "lessonTitle": "The numbers that define US healthcare", "slot": 2, "type": "connect", "brief": {"headline": "Hospital care cost $1.63 trillion in 2024 and grew 8.9%, faster than total spending at 7.2%. Day 2 showed that paying per service rewards doing more.", "kicker": "Connect day 2 and day 4: per-service pay and the hospital bill.", "fullText": "Day 2 explained fee-for-service: providers are paid for each visit, test or procedure. Day 4 showed where the biggest money goes: hospitals.\n\nPut together, more services billed in the biggest category push total spending up. Hospital care grew 8.9% in 2024, physician services 8.1%, and prescription drugs 7.9%.", "sources": [{"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}, {"url": "https://www.healthcare.gov/glossary/fee-for-service", "label": "HealthCare.gov, fee for service"}]}, "evidence": {"kind": "buildChain", "prompt": "Order how per-service pay feeds spending.", "steps": ["Providers are paid for each service", "More services are billed", "Hospital spending grows fastest", "Insurers pay more claims", "Premiums rise for employers"], "explanation": "Per-service pay rewards volume, the biggest category grows, and the cost reaches premiums."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did hospital spending grow in 2024?", "min": 0, "max": 20, "value": 8.9, "unit": "%", "explanation": "8.9%, faster than total health spending at 7.2%."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You present to a health plan. They ask where to look for savings.", "prompt": "Where do you point?", "options": ["Hospital care, the largest and fastest line", "Dental care, a small and slow-growing line", "Office supplies at clinics"], "correctIndex": 0, "consequences": ["$1.63 trillion growing 8.9% is the biggest lever.", "Small lines cannot move the total much.", "Supplies are not a spending category."], "explanation": "The biggest savings sit in the largest, fastest-growing category."}, "proReasoning": "Point to the largest line before the smallest wins.", "commonMistake": "Chasing small categories while the big one grows.", "mentalModel": "Big lines, big levers."}, "invest": {"call": {"kind": "theCall", "situation": "Hospital spending grows faster than the total.", "prompt": "Who benefits most directly?", "options": ["Patients with high deductible plans", "Hospital operators with steady volume", "Employers paying premiums"], "correctIndex": 1, "consequences": ["Patients face higher costs.", "They earn more as volume and spending grow.", "Employers pay more, not less."], "explanation": "Hospitals earn the money in the fastest-growing major category."}, "proReasoning": "Investors ask who receives each dollar of growth.", "commonMistake": "Assuming rising costs help everyone in the chain.", "mentalModel": "Follow who receives the growth."}, "build_startup": {"call": {"kind": "theCall", "situation": "You want to cut hospital spending for a health plan.", "prompt": "Which product targets volume most directly?", "options": ["A nicer patient login portal", "A billing font redesign", "A check on unneeded procedures"], "correctIndex": 2, "consequences": ["A portal does not change volume.", "Formatting does not change spending.", "Fewer unneeded services cut volume."], "explanation": "Spending rises with services billed. Cutting unneeded ones cuts cost."}, "proReasoning": "Founders aim at the driver, not the display.", "commonMistake": "Building comfort features when the buyer wants savings.", "mentalModel": "Target the driver of cost."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why hospital bills keep climbing.", "prompt": "What is one key reason?", "options": ["Providers are often paid per service", "Hospitals stopped billing insurers", "Drugs are free in hospitals"], "correctIndex": 0, "consequences": ["Paying per service rewards doing more.", "Hospitals bill insurers for most care.", "Hospital drugs are billed too."], "explanation": "Fee-for-service rewards more services, and hospitals are the biggest category."}, "proReasoning": "Ask how a provider is paid to see what it is rewarded for.", "commonMistake": "Blaming one hospital instead of how care is paid.", "mentalModel": "Payment design drives spending."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f51043d65462$ml$]::text[]),
($ml$808f2f5e-7fc5-5f33-a5b7-a7a7862cf710$ml$::uuid, $ml$healthtech$ml$, 4, 3, $ml${"id": "healthtech-d4-c3", "title": "Planning for 7.9% uninsured", "lessonTitle": "The numbers that define US healthcare", "slot": 3, "type": "decide", "brief": {"headline": "You run strategy for a hospital. 26.7 million people, 7.9% of the US, had no insurance for all of 2025.", "kicker": "Decide: how do you plan for patients without coverage?", "fullText": "Patients without insurance still come to emergency rooms, but often cannot pay their bills. That unpaid care hits a hospital's finances.\n\nYou can ignore it, plan for it in your budget, or help eligible patients enroll in coverage. Your choice affects cash flow and patients.", "sources": [{"url": "https://www.census.gov/library/publications/2026/demo/p60-291.html", "label": "US Census, health insurance coverage 2025"}, {"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects the hospital better?", "left": {"name": "Help patients enroll", "note": "Turns unpaid care into covered care"}, "right": {"name": "Send more bills", "note": "Chases patients who often cannot pay"}, "correctIndex": 0, "explanation": "Coverage turns unpaid care into paid claims. More bills rarely collect from people without means."}, "numbers": {"kind": "numberSense", "prompt": "How many million people had no insurance for all of 2025?", "min": 0, "max": 60, "value": 26.7, "unit": "M", "explanation": "26.7 million, or 7.9% of the US population."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a hospital finance team. Unpaid care is rising.", "prompt": "What do you suggest first?", "options": ["Raise prices for patients who have insurance", "Screen patients for coverage they qualify for", "Stop treating uninsured patients"], "correctIndex": 1, "consequences": ["Insurers negotiate rates; this rarely works.", "Enrolling eligible patients turns care into paid claims.", "Emergency care must still be given."], "explanation": "Some uninsured patients qualify for coverage. Enrollment helps them and the hospital."}, "proReasoning": "Finance teams fix the cause of unpaid care, not just the bills.", "commonMistake": "Treating unpaid care as only a collections problem.", "mentalModel": "Coverage beats collections."}, "invest": {"call": {"kind": "theCall", "situation": "You compare two hospitals. One treats many uninsured patients.", "prompt": "What should you check?", "options": ["How modern its lobby is", "How many parking spaces it has", "How much unpaid care it carries"], "correctIndex": 2, "consequences": ["Design says little about finances.", "Parking does not drive revenue.", "Unpaid care lowers margins."], "explanation": "Uninsured patients add unpaid care, which weighs on margins."}, "proReasoning": "Investors check the uninsured share in a hospital's area.", "commonMistake": "Ignoring payer mix when comparing hospitals.", "mentalModel": "Uninsured patients mean unpaid care."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a tool that checks patients for coverage they qualify for.", "prompt": "Who is your best buyer?", "options": ["Hospitals with many uninsured patients", "Patients who already have insurance", "Drug wholesalers"], "correctIndex": 0, "consequences": ["They gain paid claims from each enrollment.", "Insured patients do not need it.", "Wholesalers do not see patients."], "explanation": "Hospitals carry unpaid care, so they gain most from enrollment."}, "proReasoning": "Founders sell to whoever gets paid when the tool works.", "commonMistake": "Selling to people who already have the outcome.", "mentalModel": "Sell to whoever gets paid when it works."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that 7.9% of people had no insurance in 2025.", "prompt": "About how many people is that?", "options": ["About 1 in 100 people", "About 1 in 13 people", "About 1 in 3 people"], "correctIndex": 1, "consequences": ["That would be about 3.4 million.", "26.7 million people in 2025.", "That would be over 100 million."], "explanation": "7.9% is about 1 in 13 people, or 26.7 million."}, "proReasoning": "Turn percentages into \"1 in N\" to picture them.", "commonMistake": "Guessing scale without converting the percent.", "mentalModel": "Turn percents into people."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0a5e3006d15b$ml$]::text[]),
($ml$f0112008-f724-50c2-a035-f9cbc3789520$ml$::uuid, $ml$healthtech$ml$, 5, 1, $ml${"id": "healthtech-d5-c1", "title": "The drug discount app that shared too much", "lessonTitle": "The rules that protect health data", "slot": 1, "type": "apply", "brief": {"headline": "In February 2023 the FTC fined GoodRx $1.5 million, its first case under the Health Breach Notification Rule. GoodRx had shared health data with advertisers.", "kicker": "Apply the rule: who covers a drug discount app?", "fullText": "GoodRx helps people find cheaper prescription prices. The FTC said more than 55 million people had used its apps or websites since 2017.\n\nThe FTC alleged GoodRx shared users' health information with advertisers such as Facebook, while its privacy policy said it would never share health information with advertisers. GoodRx is not a doctor or insurer, so HIPAA did not apply. The FTC rule did.", "sources": [{"url": "https://www.arnoldporter.com/en/perspectives/blogs/enforcement-edge/2023/02/ftc-fines-goodrx", "label": "Arnold & Porter, FTC fines GoodRx $1.5 million"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which rule covers each one?", "buckets": ["HIPAA", "FTC rule"], "items": [{"text": "GoodRx, a drug discount app", "bucket": 1}, {"text": "A pharmacy filling your prescription", "bucket": 0}, {"text": "Your health insurer", "bucket": 0}, {"text": "A period tracker you downloaded", "bucket": 1}, {"text": "Your doctor's clinic", "bucket": 0}], "explanation": "Providers and health plans fall under HIPAA. Consumer apps like GoodRx fall under the FTC rule."}, "numbers": {"kind": "numberSense", "prompt": "How many millions of dollars was the GoodRx civil penalty?", "min": 0, "max": 5, "value": 1.5, "unit": "M", "explanation": "$1.5 million, in the first case brought under the rule."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a consumer health app as a privacy analyst.", "prompt": "Which rule do you check first?", "options": ["The FTC's Health Breach Notification Rule", "HIPAA, the rule for doctors and insurers", "No rule applies to apps"], "correctIndex": 0, "consequences": ["Consumer apps like GoodRx fall under it.", "HIPAA covers providers, plans and their partners.", "GoodRx was fined under the FTC rule."], "explanation": "Most consumer health apps are not HIPAA covered entities. The FTC rule applies."}, "proReasoning": "Privacy staff start by asking who holds the data and why.", "commonMistake": "Assuming every health app is covered by HIPAA.", "mentalModel": "Who holds the data decides the rule."}, "invest": {"call": {"kind": "theCall", "situation": "You review a health app that earns money from ads.", "prompt": "What risk does GoodRx highlight?", "options": ["Prices that are too low to earn money", "Sharing health data with advertisers", "Too few users"], "correctIndex": 1, "consequences": ["Low prices are its product.", "GoodRx paid $1.5 million for exactly that.", "GoodRx had 55 million users."], "explanation": "Ad-funded health apps risk enforcement if they share health data."}, "proReasoning": "Investors check how an app earns money and what data that uses.", "commonMistake": "Ignoring privacy risk in an ad-funded model.", "mentalModel": "Ad money plus health data is a risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your health app wants to run ads to grow.", "prompt": "What should you do first?", "options": ["Share data, then fix the policy", "Assume HIPAA does not apply to ads", "Keep health data out of ad tools"], "correctIndex": 2, "consequences": ["GoodRx shared first and was fined.", "The FTC rule still applies to apps.", "That avoids the GoodRx mistake."], "explanation": "The FTC acted because GoodRx shared health data with advertisers against its own promise."}, "proReasoning": "Founders keep data promises simple and keep them.", "commonMistake": "Writing a privacy promise the product breaks.", "mentalModel": "Never let ads see health data."}, "curiosity": {"call": {"kind": "theCall", "situation": "You use a drug discount app. You wonder if HIPAA protects you.", "prompt": "What's more accurate?", "options": ["The FTC rule likely applies", "HIPAA covers every health app", "No rule covers your data"], "correctIndex": 0, "consequences": ["GoodRx was fined under the FTC rule.", "HIPAA covers providers and plans.", "The FTC rule covers most health apps."], "explanation": "Apps outside the doctor-insurer circle usually fall under the FTC rule, not HIPAA."}, "proReasoning": "Read an app's privacy policy before sharing health details.", "commonMistake": "Assuming HIPAA follows your data everywhere.", "mentalModel": "Apps usually fall under the FTC rule."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:7c88efd3ce77$ml$]::text[]),
($ml$79755c0e-573e-5156-a32a-3718fcf29dab$ml$::uuid, $ml$healthtech$ml$, 5, 2, $ml${"id": "healthtech-d5-c2", "title": "The roles HIPAA covers", "lessonTitle": "The rules that protect health data", "slot": 2, "type": "connect", "brief": {"headline": "HIPAA covers providers, health plans and clearinghouses. Those are the payers and providers from day 1.", "kicker": "Connect day 1 and day 5: the roles decide the privacy rule.", "fullText": "Day 1 mapped payers, providers and middlemen. Day 5 showed that HIPAA covers most of them: health plans such as insurers, Medicare and Medicaid, providers that bill electronically, and clearinghouses, plus their business associates.\n\nApps outside that circle fall under the FTC's Health Breach Notification Rule. A breached app can face penalties up to $51,744 per violation.", "sources": [{"url": "https://www.hhs.gov/hipaa/for-professionals/covered-entities/index.html", "label": "HHS, HIPAA covered entities"}, {"url": "https://www.ftc.gov/business-guidance/resources/health-breach-notification-rule-basics-business", "label": "FTC, Health Breach Notification Rule basics"}, {"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Which of these is a HIPAA covered entity?", "options": ["Medicare", "A step-counting app", "A fitness tracker maker"], "correctIndex": 0, "explanation": "Medicare is a health plan. Consumer apps and devices usually fall under the FTC rule."}, "numbers": {"kind": "numberSense", "prompt": "Up to how many thousand dollars per violation can a breached app face?", "min": 0, "max": 80, "value": 51.7, "unit": "K", "explanation": "Up to $51,744 per violation under the FTC rule."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a data role at an insurer.", "prompt": "Which rule governs the patient data you will handle?", "options": ["No federal rule", "HIPAA, as the insurer is a health plan", "The FTC rule written for consumer apps"], "correctIndex": 1, "consequences": ["HIPAA applies to insurers.", "Health plans are HIPAA covered entities.", "That rule covers apps outside HIPAA."], "explanation": "Insurers are health plans, which HIPAA covers."}, "proReasoning": "Map a company to its day 1 role to know its privacy rule.", "commonMistake": "Applying the app rule to an insurer.", "mentalModel": "The role decides the rule."}, "invest": {"call": {"kind": "theCall", "situation": "An app signs a deal to process data for hospitals.", "prompt": "How might its rules change?", "options": ["Nothing changes for its legal duties", "It escapes all rules", "It may become a HIPAA business associate"], "correctIndex": 2, "consequences": ["Serving hospitals changes its obligations.", "Business associates face HIPAA rules.", "Working for covered entities brings HIPAA duties."], "explanation": "Business associates that help covered entities must follow HIPAA."}, "proReasoning": "Investors check whether a new customer brings new rules.", "commonMistake": "Missing the compliance cost of a new customer type.", "mentalModel": "New customers can bring new rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan to sell your app to clinics instead of consumers.", "prompt": "What must you prepare for?", "options": ["HIPAA duties as a business associate", "Fewer privacy rules than before", "No privacy checks at all"], "correctIndex": 0, "consequences": ["Clinics are covered entities; their partners follow HIPAA.", "Serving clinics adds duties.", "Clinics will require HIPAA terms."], "explanation": "Selling to covered entities makes you a business associate under HIPAA."}, "proReasoning": "Founders price compliance into each go-to-market choice.", "commonMistake": "Switching customers without checking the new rules.", "mentalModel": "Who you serve sets your rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "You share health details with your insurer and with a fitness app.", "prompt": "Are both protected the same way?", "options": ["Neither is protected", "No, HIPAA covers the insurer only", "Yes, HIPAA covers both of them equally"], "correctIndex": 1, "consequences": ["Both are covered, by different rules.", "Insurers are covered; most apps fall under the FTC.", "Most consumer apps are outside HIPAA."], "explanation": "Your insurer is a HIPAA health plan. Most fitness apps fall under the FTC rule."}, "proReasoning": "Ask who holds your data to know which rule protects it.", "commonMistake": "Assuming all health data gets the same protection.", "mentalModel": "Same data, different rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:df0fc0a7f089$ml$]::text[]),
($ml$86d08ee8-a6f7-5982-a83d-9a1f57930ab8$ml$::uuid, $ml$healthtech$ml$, 5, 3, $ml${"id": "healthtech-d5-c3", "title": "Consumer app or clinic tool?", "lessonTitle": "The rules that protect health data", "slot": 3, "type": "decide", "brief": {"headline": "You built a symptom tracker. You can sell it to consumers, or to clinics that share it with their patients.", "kicker": "Decide: which path, and which privacy rule comes with it?", "fullText": "Sold to consumers, the app falls under the FTC's Health Breach Notification Rule. GoodRx paid $1.5 million under that rule after sharing health data with advertisers.\n\nSold to clinics, the app works for HIPAA covered entities and would likely be a business associate under HIPAA. Each path brings different buyers and duties.", "sources": [{"url": "https://www.ftc.gov/business-guidance/resources/health-breach-notification-rule-basics-business", "label": "FTC, Health Breach Notification Rule basics"}, {"url": "https://www.hhs.gov/hipaa/for-professionals/covered-entities/index.html", "label": "HHS, HIPAA covered entities"}, {"url": "https://www.arnoldporter.com/en/perspectives/blogs/enforcement-edge/2023/02/ftc-fines-goodrx", "label": "Arnold & Porter, FTC fines GoodRx $1.5 million"}]}, "evidence": {"kind": "faceOff", "prompt": "Which path brings HIPAA duties?", "left": {"name": "Selling to clinics", "note": "Works for covered entities"}, "right": {"name": "Selling to consumers", "note": "Downloaded by individuals"}, "correctIndex": 0, "explanation": "Partners of covered entities follow HIPAA. Consumer apps usually fall under the FTC rule."}, "numbers": {"kind": "numberSense", "prompt": "How many million people had used GoodRx since 2017, per the FTC?", "min": 0, "max": 100, "value": 55, "unit": "M", "explanation": "More than 55 million. Scale makes privacy mistakes costly."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the first compliance hire. The team picks the clinic path.", "prompt": "What do you set up first?", "options": ["An ad network integration for growth", "Nothing until a breach", "A business associate agreement process"], "correctIndex": 2, "consequences": ["Ads with health data invite enforcement.", "Waiting turns duties into fines.", "Clinics will require HIPAA agreements."], "explanation": "Business associates sign agreements and follow HIPAA safeguards."}, "proReasoning": "Compliance hires build the basics before the first contract.", "commonMistake": "Waiting for a problem before setting up duties.", "mentalModel": "Set up duties before the first deal."}, "invest": {"call": {"kind": "theCall", "situation": "Two similar trackers raise money. One sells to clinics, one to consumers.", "prompt": "What difference should you weigh?", "options": ["Different buyers and privacy duties", "They face the exact same privacy rules", "Only the logo differs"], "correctIndex": 0, "consequences": ["Clinics bring HIPAA; consumers bring the FTC rule.", "The rules differ by who they serve.", "The models differ deeply."], "explanation": "The customer decides the rule, the sales cycle and the risks."}, "proReasoning": "Investors compare go-to-market and its compliance cost together.", "commonMistake": "Comparing products and ignoring who they sell to.", "mentalModel": "The buyer changes the business."}, "build_startup": {"call": {"kind": "theCall", "situation": "You have six months of runway and need revenue fast.", "prompt": "Which path fits that constraint?", "options": ["Both at once with half a team", "Consumers, with strict data rules", "Clinics, with long sales cycles"], "correctIndex": 1, "consequences": ["Splitting a small team slows both.", "Faster to launch, if you keep health data private.", "Clinic deals often take many months."], "explanation": "Consumer apps can launch faster, but must follow the FTC rule closely."}, "proReasoning": "Founders match the path to their runway, then follow its rules.", "commonMistake": "Choosing a long sales cycle with short runway.", "mentalModel": "Match the path to your runway."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your clinic gives you a symptom app to use.", "prompt": "Which rule likely protects your data?", "options": ["Only the FTC rule for apps", "No rule at all", "HIPAA, through the clinic"], "correctIndex": 2, "consequences": ["The FTC rule covers apps outside HIPAA.", "Clinic tools carry HIPAA duties.", "An app working for the clinic follows HIPAA."], "explanation": "An app the clinic provides likely works as its business associate under HIPAA."}, "proReasoning": "Ask whether an app came from your doctor or a store.", "commonMistake": "Thinking the same app always has the same rule.", "mentalModel": "Where an app comes from matters."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:125256575937$ml$]::text[]),
($ml$a9bc2d2e-b33c-575f-843a-bb0fe2589515$ml$::uuid, $ml$healthtech$ml$, 6, 1, $ml${"id": "healthtech-d6-c1", "title": "Hospitals back on paper", "lessonTitle": "One hack that froze healthcare billing", "slot": 1, "type": "apply", "brief": {"headline": "A ransomware attack hit Ascension, one of the largest US health systems, on May 8, 2024. Data on 5,599,699 people was affected.", "kicker": "Apply the lesson: what happens when a hospital system goes dark?", "fullText": "After the attack, Ascension hospitals switched to downtime procedures, working on paper, and diverted some ambulances to other hospitals. Most services were restored by mid-June.\n\nLike the Change Healthcare attack, the damage went beyond stolen data. When core systems go down, care and billing slow at the same time.", "sources": [{"url": "https://www.securityweek.com/5-6-million-impacted-by-ransomware-attack-on-healthcare-giant-ascension/", "label": "SecurityWeek, 5.6 million affected by Ascension ransomware attack"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Ascension attack in order.", "steps": ["Ransomware hits Ascension on May 8, 2024", "Core systems go offline", "Staff switch to paper downtime procedures", "Some ambulances are diverted elsewhere", "Most services are restored by mid-June"], "explanation": "The attack took systems offline, care slowed, and recovery took about five weeks."}, "numbers": {"kind": "numberSense", "prompt": "How many million people were affected by the Ascension attack?", "min": 0, "max": 10, "value": 5.6, "unit": "M", "explanation": "5,599,699 people, or about 5.6 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a hospital IT team after a ransomware attack like Ascension's.", "prompt": "What do you make sure exists first?", "options": ["A plan to pay any ransom quickly", "Tested paper downtime procedures", "A new logo for the patient portal"], "correctIndex": 1, "consequences": ["Paying does not guarantee systems come back.", "Staff can keep caring for patients while systems are down.", "A logo does nothing when systems are offline."], "explanation": "Ascension relied on downtime procedures for weeks. Staff need to practice them before an attack."}, "proReasoning": "Hospital IT teams rehearse working without systems, not just protecting them.", "commonMistake": "Planning only to prevent attacks, not to keep working through one.", "mentalModel": "Plan to work while systems are down."}, "invest": {"call": {"kind": "theCall", "situation": "You own bonds of a hospital system hit by ransomware.", "prompt": "What cost is easiest to miss at first?", "options": ["The price of new screens and laptops for staff", "A drop in its brand awareness", "Lost revenue while care and billing slow"], "correctIndex": 2, "consequences": ["Hardware is a small cost next to lost revenue.", "Awareness is not what pays the bonds.", "Diverted patients and slow billing cut cash for weeks."], "explanation": "When systems go down for weeks, patients are diverted and claims slow down."}, "proReasoning": "Investors model weeks of lost revenue, not just the cleanup bill.", "commonMistake": "Counting only the IT repair cost of an attack.", "mentalModel": "Downtime costs revenue, not just repairs."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software for hospitals. A buyer asks what happens if your system goes down.", "prompt": "What is the strongest answer?", "options": ["A tested offline mode staff can use", "Our system never goes down", "Call our support line and wait"], "correctIndex": 0, "consequences": ["Shows you planned for the Ascension-type case.", "No buyer believes a promise of zero downtime.", "Waiting is what hospitals fear most."], "explanation": "After attacks like Ascension's, buyers ask how care continues without your system."}, "proReasoning": "Founders show how their product fails safely, not that it never fails.", "commonMistake": "Promising perfect uptime to a buyer who has lived through an attack.", "mentalModel": "Show how you fail safely."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear a hospital is using paper charts for a few weeks.", "prompt": "What is the most likely reason?", "options": ["It is saving money on software", "Its computer systems were attacked or down", "Paper charts are now required by federal law"], "correctIndex": 1, "consequences": ["Hospitals rarely drop software to save money.", "Ascension used paper procedures after ransomware.", "No law requires hospitals to go back to paper."], "explanation": "Hospitals switch to paper downtime procedures when core systems are unavailable."}, "proReasoning": "Paper at a modern hospital is often a sign of an outage.", "commonMistake": "Assuming paper means the hospital is behind the times.", "mentalModel": "Paper charts can signal an outage."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0e8b15d50bad$ml$]::text[]),
($ml$a5b306f9-8d76-5636-824f-b4fcebce3edf$ml$::uuid, $ml$healthtech$ml$, 6, 2, $ml${"id": "healthtech-d6-c2", "title": "The clearinghouse in the middle", "lessonTitle": "One hack that froze healthcare billing", "slot": 2, "type": "connect", "brief": {"headline": "Day 5 showed that HIPAA covers health care clearinghouses. Change Healthcare is one, and its 2024 breach exposed data on about 192.7 million people.", "kicker": "Connect day 5 and day 6: a covered middleman became a single point of failure.", "fullText": "Clearinghouses pass claims between providers and payers. Because they handle health data for both, HIPAA covers them like insurers and providers.\n\nChange Healthcare processes claims for much of the system. Its breached portal had no multi-factor authentication. Exposed data included insurance IDs, diagnoses, treatments and Social Security numbers.", "sources": [{"url": "https://www.hhs.gov/hipaa/for-professionals/covered-entities/index.html", "label": "HHS, HIPAA covered entities"}, {"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, Change Healthcare hack affected 192.7 million"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Clearinghouses are HIPAA covered entities.", "The breached Change portal used multi-factor login.", "The breach exposed data on about 192.7 million people."], "fakeIndex": 1, "explanation": "UnitedHealth's CEO testified the portal did not have multi-factor authentication."}, "numbers": {"kind": "numberSense", "prompt": "How many million people had data exposed in the Change Healthcare breach?", "min": 0, "max": 350, "value": 193, "unit": "M", "explanation": "About 192.7 million, one of the largest health data breaches ever."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a security role at a claims processor.", "prompt": "Which lesson from Change Healthcare do you lead with?", "options": ["Store fewer claims on its servers each year", "Move all data to paper", "Require multi-factor login on every portal"], "correctIndex": 2, "consequences": ["Claims volume is the business, not the flaw.", "Paper cannot process claims at scale.", "The breached portal had no multi-factor authentication."], "explanation": "The attackers got in through a portal without multi-factor authentication."}, "proReasoning": "Security candidates tie their first fix to a real failure.", "commonMistake": "Proposing big changes before closing the known gap.", "mentalModel": "Close the known gap first."}, "invest": {"call": {"kind": "theCall", "situation": "You compare health IT companies. One is a clearinghouse.", "prompt": "What extra risk does that role carry?", "options": ["A breach can hit providers and payers at once", "It faces fewer privacy rules than any app", "It holds no patient data"], "correctIndex": 0, "consequences": ["It sits between both, so an outage spreads widely.", "Clearinghouses fall under HIPAA.", "Claims carry diagnoses and insurance IDs."], "explanation": "A clearinghouse sits between providers and payers, so a breach spreads both ways."}, "proReasoning": "Investors price the blast radius of a company's role.", "commonMistake": "Treating a middleman as low risk because patients never see it.", "mentalModel": "Middlemen carry wide risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You plan to launch a small claims clearinghouse.", "prompt": "Which duty applies from day one?", "options": ["No rules until you are large", "HIPAA, as a covered entity", "Only the FTC app rule"], "correctIndex": 1, "consequences": ["HIPAA does not wait for size.", "HIPAA names clearinghouses as covered entities.", "That rule is for apps outside HIPAA."], "explanation": "Clearinghouses are covered entities, so HIPAA applies from the start."}, "proReasoning": "Founders check their role on the HIPAA list before writing code.", "commonMistake": "Assuming a small startup is too small to be covered.", "mentalModel": "Your role, not size, sets the rules."}, "curiosity": {"call": {"kind": "theCall", "situation": "You never used Change Healthcare. You got a breach notice anyway.", "prompt": "How is that possible?", "options": ["You signed up for it by mistake", "Notices are sent to everyone", "Your providers sent claims through it"], "correctIndex": 2, "consequences": ["Patients do not sign up for clearinghouses.", "Notices go to people whose data was exposed.", "Clearinghouses handle claims patients never see."], "explanation": "Clearinghouses process claims between your doctor and your insurer behind the scenes."}, "proReasoning": "Ask your insurer which middlemen handle your claims.", "commonMistake": "Assuming only companies you chose hold your data.", "mentalModel": "Middlemen you never chose hold your data."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:f64db343dee8$ml$]::text[]),
($ml$42e3c344-fcd8-543a-b3e7-17da4a50670b$ml$::uuid, $ml$healthtech$ml$, 6, 3, $ml${"id": "healthtech-d6-c3", "title": "One clearinghouse or two?", "lessonTitle": "One hack that froze healthcare billing", "slot": 3, "type": "decide", "brief": {"headline": "You run billing for a group of clinics. All your claims go through one clearinghouse. The Change Healthcare attack showed what happens when that link breaks.", "kicker": "Decide: do you add a backup claims route?", "fullText": "Depending on one claims processor is a single point of failure. When Change Healthcare went down in 2024, many providers could not send claims.\n\nA second clearinghouse costs money and setup time. Going without one saves money until the day the only route fails.", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, Change Healthcare hack affected 192.7 million"}]}, "evidence": {"kind": "faceOff", "prompt": "Which setup keeps cash coming if one route fails?", "left": {"name": "Two claims routes", "note": "A backup clearinghouse is set up and tested"}, "right": {"name": "One claims route", "note": "Cheaper, with no fallback"}, "correctIndex": 0, "explanation": "A tested backup lets claims keep flowing when the main processor is down."}, "numbers": {"kind": "numberSense", "prompt": "About how many weeks did Ascension take to restore most services?", "min": 0, "max": 10, "value": 6, "unit": "weeks", "explanation": "From May 8 to mid-June 2024, about five to six weeks.", "sources": ["sw_ascension"]}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks whether a backup clearinghouse is worth the cost.", "prompt": "What do you recommend?", "options": ["Set one up and test it", "Skip it; outages are rare", "Keep a list of vendors to call later"], "correctIndex": 0, "consequences": ["Claims keep moving if the main route fails.", "Change Healthcare showed rare outages can last weeks.", "Setup takes time you will not have mid-crisis."], "explanation": "Outages are rare but long. A tested backup is ready when it is needed."}, "proReasoning": "Billing leaders price the cost of weeks without claims.", "commonMistake": "Judging a backup by how often outages happen.", "mentalModel": "Price the outage, not its odds."}, "invest": {"call": {"kind": "theCall", "situation": "You review a clinic chain. It uses a single clearinghouse with no backup.", "prompt": "How do you treat that?", "options": ["Irrelevant to its finances", "A cash flow risk worth asking about", "A smart way to save money on vendors"], "correctIndex": 1, "consequences": ["Claims are how the chain gets paid.", "One route failing can stop claims for weeks.", "The savings vanish in one long outage."], "explanation": "A single claims route can freeze revenue when it fails."}, "proReasoning": "Investors ask how a provider gets paid if its main vendor fails.", "commonMistake": "Ignoring vendor risk in a provider's finances.", "mentalModel": "Vendor risk is revenue risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could build tools that switch claims to a backup clearinghouse automatically.", "prompt": "Who is the best first buyer?", "options": ["Patients who pay their own bills", "Clearinghouses that want no rivals", "Provider groups hurt by the 2024 outage"], "correctIndex": 2, "consequences": ["Patients do not send claims.", "They would rather keep all the volume.", "They felt the pain and want a fallback."], "explanation": "Providers who lived through the outage value a fast switch."}, "proReasoning": "Founders sell to buyers who recently felt the pain.", "commonMistake": "Selling resilience to the vendor it replaces.", "mentalModel": "Sell to who felt the pain."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your doctor says billing was delayed for weeks in 2024.", "prompt": "What is a likely cause?", "options": ["A claims processor outage", "A new law against billing", "Patients stopped paying"], "correctIndex": 0, "consequences": ["Change Healthcare's outage stalled many claims.", "No law stopped billing in 2024.", "Most payment comes from insurers."], "explanation": "When a clearinghouse goes down, providers cannot send claims to insurers."}, "proReasoning": "Billing delays often trace back to a middleman.", "commonMistake": "Blaming the doctor for a delay in a hidden link.", "mentalModel": "Delays often hide in the middle."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:278753afad71$ml$]::text[]),
($ml$14f65dc6-5396-5123-a532-58edf2fb3963$ml$::uuid, $ml$healthtech$ml$, 7, 1, $ml${"id": "healthtech-d7-c1", "title": "CVS buys value-based clinics", "lessonTitle": "Paying for outcomes, not visits", "slot": 1, "type": "apply", "brief": {"headline": "CVS Health closed its $10.6 billion purchase of Oak Street Health on May 2, 2023. Oak Street runs value-based primary care clinics for Medicare patients.", "kicker": "Apply value-based care: why pay billions for clinics?", "fullText": "Oak Street had more than 160 clinics in 21 states when the deal closed. Its model is value-based: it is paid partly for keeping patients healthy and costs down, not only per visit.\n\nCVS already owned the insurer Aetna. Owning clinics paid on outcomes adds another piece of the chain.", "sources": [{"url": "https://www.beckershospitalreview.com/disruptors/cvs-closes-10-6b-acquisition-of-oak-street-health/", "label": "Becker's, CVS closes $10.6B acquisition of Oak Street Health"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each feature reward volume or value?", "buckets": ["Volume", "Value"], "items": [{"text": "Paying a clinic for each visit", "bucket": 0}, {"text": "Sharing savings when costs come in low", "bucket": 1}, {"text": "Bonuses tied to quality measures", "bucket": 1}, {"text": "More procedures, more revenue", "bucket": 0}, {"text": "Taking joint responsibility for patient costs", "bucket": 1}], "explanation": "Per-visit pay rewards volume. Shared savings and quality bonuses reward value."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did CVS pay for Oak Street Health?", "min": 0, "max": 25, "value": 10.6, "unit": "B", "explanation": "$10.6 billion, closed May 2, 2023."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at a value-based clinic chain like Oak Street.", "prompt": "What do you say drives its success?", "options": ["Booking as many visits as possible", "Charging higher prices per visit", "Keeping patients healthy at lower cost"], "correctIndex": 2, "consequences": ["Extra visits do not raise value-based pay.", "Its revenue is not built on per-visit prices.", "Value-based pay rewards outcomes and lower costs."], "explanation": "Value-based clinics earn more when patients stay healthy and costs stay low."}, "proReasoning": "Strong candidates explain how a company is paid before what it does.", "commonMistake": "Describing a value-based clinic in fee-for-service terms.", "mentalModel": "Know how the company gets paid."}, "invest": {"call": {"kind": "theCall", "situation": "CVS paid $10.6 billion for clinics serving Medicare patients.", "prompt": "What must happen for the deal to pay off?", "options": ["Patients cost less than the clinics are paid", "Clinics book many more visits each year", "Oak Street raises its visit prices"], "correctIndex": 0, "consequences": ["Value-based margins come from cost below payment.", "Visit counts are not the main lever here.", "Value-based pay is not set per visit."], "explanation": "In value-based care, profit is the gap between payment and the real cost of care."}, "proReasoning": "Investors judge value-based deals on cost of care per patient.", "commonMistake": "Valuing a value-based clinic on visit growth.", "mentalModel": "Value-based profit is payment minus cost."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app helps patients manage chronic conditions between visits.", "prompt": "Who is the strongest buyer?", "options": ["Patients paying out of pocket", "Value-based clinics like Oak Street", "Clinics paid only per visit"], "correctIndex": 1, "consequences": ["Patients rarely pay for such tools.", "They gain when patients stay healthy and out of hospitals.", "Fewer visits can cut their revenue."], "explanation": "Value-based clinics keep the savings when patients stay well."}, "proReasoning": "Founders sell prevention to whoever keeps the savings.", "commonMistake": "Selling prevention to a buyer paid for treatment.", "mentalModel": "Sell prevention to who keeps savings."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend asks why a pharmacy company would buy doctors' offices.", "prompt": "What is the best answer?", "options": ["To sell more snacks in clinics", "Because pharmacies must own clinics", "To earn from keeping patients healthy"], "correctIndex": 2, "consequences": ["Clinics are about care, not retail sales.", "No rule requires pharmacies to own clinics.", "Oak Street is paid partly for outcomes and lower costs."], "explanation": "CVS bought clinics paid on value, adding care to its insurer and pharmacies."}, "proReasoning": "Ask how the bought company is paid to see the logic of a deal.", "commonMistake": "Assuming the deal is about store traffic.", "mentalModel": "Deals follow how money is earned."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:287892ffa8f8$ml$]::text[]),
($ml$36d43e19-2231-528b-a253-5645dde28ec2$ml$::uuid, $ml$healthtech$ml$, 7, 2, $ml${"id": "healthtech-d7-c2", "title": "Volume pay meets shared savings", "lessonTitle": "Paying for outcomes, not visits", "slot": 2, "type": "connect", "brief": {"headline": "Day 2 showed that fee-for-service pays per visit, test or procedure. Medicare's accountable care organizations try another way, and saved a record $2.4 billion in 2024.", "kicker": "Connect day 2 and day 7: from paying for volume to paying for value.", "fullText": "Under fee-for-service, more services mean more pay. An accountable care organization, or ACO, is a group of providers that takes joint responsibility for its patients' cost and quality.\n\nIn 2024, 476 Medicare ACOs saved the program $2.4 billion. They also improved blood pressure control, A1c levels and depression follow-up. ACOs still bill per service, but share savings when costs come in below a benchmark.", "sources": [{"url": "https://www.healthcare.gov/glossary/fee-for-service", "label": "HealthCare.gov, fee for service"}, {"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, MSSP ACOs saved $2.4B in 2024"}]}, "evidence": {"kind": "faceOff", "prompt": "A clinic cuts unneeded tests. Under which model does it gain?", "left": {"name": "An ACO", "note": "Shares savings below a benchmark"}, "right": {"name": "Pure fee-for-service", "note": "Paid for every test it bills"}, "correctIndex": 0, "explanation": "The ACO shares the savings. Under pure fee-for-service, fewer tests mean less revenue."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did Medicare ACOs save the program in 2024?", "min": 0, "max": 6, "value": 2.4, "unit": "B", "explanation": "A record $2.4 billion in net savings."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A health system asks you to explain ACOs to its doctors in one line.", "prompt": "Which line is most accurate?", "options": ["You still bill, but share savings you create", "You stop billing Medicare for any service", "You get paid only for more visits"], "correctIndex": 0, "consequences": ["ACOs share savings below a benchmark.", "ACO providers still bill per service.", "That describes fee-for-service."], "explanation": "ACOs layer shared savings and quality bonuses on top of normal billing."}, "proReasoning": "Explain a new model by what changes and what stays the same.", "commonMistake": "Telling doctors value-based care ends billing.", "mentalModel": "Say what changes and what stays."}, "invest": {"call": {"kind": "theCall", "situation": "Medicare ACOs saved a record $2.4 billion in 2024.", "prompt": "Which companies does that trend help most?", "options": ["Firms selling paper records", "Firms that help providers cut costs", "Firms that profit from more tests"], "correctIndex": 1, "consequences": ["Paper does not help ACOs.", "ACOs reward lower costs, so cost tools gain.", "Volume-driven firms gain less as value grows."], "explanation": "As more pay rewards savings, tools that cut costs gain buyers."}, "proReasoning": "Investors follow which behavior a payment model rewards.", "commonMistake": "Betting on volume while payment shifts to value.", "mentalModel": "Follow what the payment rewards."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your tool flags patients likely to end up in the hospital.", "prompt": "Which buyer gains most from it?", "options": ["A hospital paid for each admission", "A lab paid per test", "An ACO sharing in Medicare savings"], "correctIndex": 2, "consequences": ["Fewer admissions cut its revenue.", "A lab gains nothing from fewer admissions.", "Avoided admissions lower costs the ACO shares."], "explanation": "An ACO gains when costly hospital stays are avoided."}, "proReasoning": "Founders check that the buyer wins when the product works.", "commonMistake": "Selling avoided admissions to the hospital that loses them.", "mentalModel": "The buyer must win when you work."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your doctor's group calls itself an ACO.", "prompt": "What does that mean for how it is paid?", "options": ["It can share savings if costs stay low", "It no longer bills Medicare at all", "It is paid only by patients"], "correctIndex": 0, "consequences": ["ACOs share savings and earn quality bonuses.", "ACO providers still bill Medicare.", "Medicare still pays most of the cost."], "explanation": "ACO members still bill, but also share savings and quality bonuses."}, "proReasoning": "Ask your doctor's group how it is rewarded for keeping you healthy.", "commonMistake": "Thinking an ACO is a new kind of insurance.", "mentalModel": "An ACO is a way of paying providers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b6e3fd678c85$ml$]::text[]),
($ml$aa6702a0-c5cc-5cec-a7c4-5c96e5bcceb1$ml$::uuid, $ml$healthtech$ml$, 7, 3, $ml${"id": "healthtech-d7-c3", "title": "Joining an ACO", "lessonTitle": "Paying for outcomes, not visits", "slot": 3, "type": "decide", "brief": {"headline": "You run a 20-doctor primary care group paid fee-for-service. A local ACO invites you to join. In 2024, 476 Medicare ACOs saved $2.4 billion.", "kicker": "Decide: what do you need before saying yes?", "fullText": "Joining means sharing responsibility for your patients' total cost and quality. If costs come in below a benchmark, you share the savings. You also report quality measures.\n\nYou need data on your patients' costs, and a way to track quality, to know if you can win.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, MSSP ACOs saved $2.4B in 2024"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What do you need most before joining an ACO?", "options": ["A larger waiting room for patients", "A new phone system", "Data on your patients' total costs"], "correctIndex": 2, "explanation": "ACO savings are measured against a cost benchmark. Without cost data you cannot manage it."}, "numbers": {"kind": "numberSense", "prompt": "How many Medicare ACOs took part in 2024?", "min": 0, "max": 800, "value": 476, "unit": "ACOs", "explanation": "476 ACOs, which together saved $2.4 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage operations for the group. The doctors ask what changes if they join.", "prompt": "What is the biggest change?", "options": ["Stopping all billing at once", "Tracking cost and quality for patients", "Seeing far more patients every day"], "correctIndex": 1, "consequences": ["ACO providers keep billing.", "ACO rewards depend on cost and quality results.", "Volume is not what ACOs reward."], "explanation": "ACOs judge groups on total cost and quality, so tracking both matters."}, "proReasoning": "Operations leaders prepare the data before the contract starts.", "commonMistake": "Joining without a way to measure results.", "mentalModel": "Measure before you sign."}, "invest": {"call": {"kind": "theCall", "situation": "You consider funding a group that just joined an ACO.", "prompt": "What is the key question?", "options": ["How many visits does it book a year?", "How big is its office?", "Can it keep costs below the benchmark?"], "correctIndex": 2, "consequences": ["Visits matter less in value-based pay.", "Office size says nothing about savings.", "Shared savings depend on beating the benchmark."], "explanation": "An ACO member earns extra only when costs come in below the benchmark."}, "proReasoning": "Investors ask how a group will beat its target, not just join.", "commonMistake": "Counting the upside without asking how it is earned.", "mentalModel": "Upside must be earned against a target."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup could serve groups joining ACOs.", "prompt": "What product fits their first need?", "options": ["Patient cost and quality dashboards", "A booking app to add visits", "A billing tool for higher fees"], "correctIndex": 0, "consequences": ["They must track cost and quality to share savings.", "More visits is not the ACO goal.", "Higher fees do not lower total costs."], "explanation": "New ACO members need to see costs and quality to manage them."}, "proReasoning": "Founders build what a new rule forces buyers to do.", "commonMistake": "Building volume tools for a value-based buyer.", "mentalModel": "Build what the new model demands."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your doctor starts calling to check on you between visits.", "prompt": "Why might that be?", "options": ["A new law requires daily calls", "The group may be rewarded for your health", "The group needs to book more visits"], "correctIndex": 1, "consequences": ["No law requires such calls.", "Value-based groups gain when patients stay well.", "Calls between visits are not billed visits."], "explanation": "Groups in value-based models gain when patients avoid costly care."}, "proReasoning": "Notice how a provider's pay shapes how it treats you.", "commonMistake": "Assuming extra contact means extra billing.", "mentalModel": "Pay shapes how care feels."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:eba56bc5d05d$ml$]::text[]),
($ml$0014b81d-7918-55b8-a55c-2cfe9933805a$ml$::uuid, $ml$healthtech$ml$, 8, 1, $ml${"id": "healthtech-d8-c1", "title": "Diagnoses added after the visit", "lessonTitle": "Medicare Advantage costs more", "slot": 1, "type": "apply", "brief": {"headline": "Kaiser Permanente affiliates agreed on January 14, 2026, to pay $556 million to settle claims they inflated Medicare Advantage payments. They did not admit liability.", "kicker": "Apply coding intensity: how do extra diagnoses raise payments?", "fullText": "The Justice Department alleged that from 2009 to 2018, Kaiser pressured doctors to add diagnoses to patient records after visits, through addenda, sometimes more than a year later. More diagnoses raise risk scores, and higher risk scores raise Medicare Advantage payments.\n\nThe whistleblowers who brought the case will receive about $95 million. The claims are allegations only; there was no finding of liability.", "sources": [{"url": "https://www.justice.gov/opa/pr/kaiser-permanente-affiliates-pay-556m-resolve-false-claims-act-allegations", "label": "US Justice Department, Kaiser Permanente affiliates pay $556M"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Kaiser affiliates agreed to pay $556 million.", "The settlement included a finding of liability.", "The alleged conduct ran from 2009 to 2018."], "fakeIndex": 1, "explanation": "The settlement says the claims are allegations only, with no determination of liability."}, "numbers": {"kind": "numberSense", "prompt": "How many millions did Kaiser affiliates agree to pay?", "min": 0, "max": 1000, "value": 556, "unit": "M", "explanation": "$556 million, with about $95 million going to the whistleblowers."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a Medicare Advantage plan's compliance team.", "prompt": "Which practice do you watch most closely?", "options": ["Diagnoses added long after a visit", "How fast members get ID cards", "The color of plan brochures"], "correctIndex": 0, "consequences": ["Late addenda were central to the Kaiser allegations.", "Card speed is service, not payment risk.", "Design has no effect on payments."], "explanation": "Diagnoses drive risk scores and payments, so late additions draw scrutiny."}, "proReasoning": "Compliance staff follow the data that sets payment.", "commonMistake": "Auditing service details while coding drives the money.", "mentalModel": "Watch the data that sets payment."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in a Medicare Advantage insurer.", "prompt": "What does the Kaiser settlement signal?", "options": ["Diagnoses no longer affect pay", "Coding practices carry legal risk", "Medicare Advantage is ending"], "correctIndex": 1, "consequences": ["Risk scores still set payments.", "Settlements over coding can reach hundreds of millions.", "The program continues; it is not ending."], "explanation": "Regulators are pursuing how plans record diagnoses, with large settlements."}, "proReasoning": "Investors add legal risk to plans that grow through coding.", "commonMistake": "Treating coding gains as risk-free revenue.", "mentalModel": "Coding gains can carry legal costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell chart review software to Medicare Advantage plans.", "prompt": "How should you position it after Kaiser?", "options": ["As a way to add more diagnoses", "As a way to skip any doctor review", "As a tool for accurate, timely records"], "correctIndex": 2, "consequences": ["That framing invites the scrutiny Kaiser faced.", "Removing doctors raises compliance risk.", "Accuracy is what regulators reward."], "explanation": "Selling \"more diagnoses\" now reads as legal risk. Accuracy is the safer pitch."}, "proReasoning": "Founders frame products around what regulators want to see.", "commonMistake": "Pitching revenue lift where regulators see abuse.", "mentalModel": "Sell accuracy, not inflation."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that a health system paid $556 million over diagnoses.", "prompt": "Why do diagnoses matter so much?", "options": ["They raise what Medicare pays the plan", "They set the price of drugs", "They decide hospital parking fees"], "correctIndex": 0, "consequences": ["Higher risk scores mean higher plan payments.", "Drug prices are set separately.", "Parking has nothing to do with it."], "explanation": "In Medicare Advantage, more recorded diagnoses raise risk scores and payments."}, "proReasoning": "Ask how a record is used to see why it is worth getting right.", "commonMistake": "Thinking diagnoses are only medical notes.", "mentalModel": "Diagnoses can move money."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:4bfce9f43c08$ml$]::text[]),
($ml$df994bbc-2a2b-57bd-8a77-33461fcc0eca$ml$::uuid, $ml$healthtech$ml$, 8, 2, $ml${"id": "healthtech-d8-c2", "title": "The extra $84 billion", "lessonTitle": "Medicare Advantage costs more", "slot": 2, "type": "connect", "brief": {"headline": "Medicare spending grew 7.8% in 2024, as day 4 showed. MedPAC projected that Medicare Advantage would cost about $84 billion more in 2025 than the same people in traditional Medicare.", "kicker": "Connect day 4 and day 8: part of Medicare growth is how it pays plans.", "fullText": "Medicare was projected to pay private Medicare Advantage plans $538 billion in 2025, about 20% more than traditional Medicare would cost for the same people.\n\nMedPAC split the gap into two drivers. Favorable selection, healthier members joining MA, added about $44 billion. Coding intensity, recording more diagnoses, added about $40 billion.", "sources": [{"url": "https://www.cms.gov/data-research/statistics-trends-and-reports/national-health-expenditure-data/nhe-fact-sheet", "label": "CMS, National Health Expenditure fact sheet"}, {"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, Medicare Advantage to cost $84 billion more in 2025"}]}, "evidence": {"kind": "sortSignal", "prompt": "Which driver of the extra cost is each one?", "buckets": ["Favorable selection", "Coding intensity"], "items": [{"text": "Healthier people choosing MA plans", "bucket": 0}, {"text": "Recording more diagnoses per member", "bucket": 1}, {"text": "Risk scores rising faster than in traditional Medicare", "bucket": 1}, {"text": "Members costing less than their risk scores predict", "bucket": 0}], "explanation": "Selection is about who joins. Coding is about how much gets recorded."}, "numbers": {"kind": "numberSense", "prompt": "How many billions more did MedPAC estimate MA would cost in 2025?", "min": 0, "max": 150, "value": 84, "unit": "B", "explanation": "About $84 billion, or 20% more than traditional Medicare."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You brief a lawmaker's staff on why Medicare costs keep rising.", "prompt": "Which point links day 4 and day 8?", "options": ["Medicare only pays for drugs", "MA plans cost more than traditional Medicare", "Medicare stopped paying for hospital care"], "correctIndex": 1, "consequences": ["Medicare covers far more than drugs.", "MedPAC put the gap at about $84 billion.", "Medicare still pays hospitals."], "explanation": "Part of Medicare's growth comes from paying MA plans more than traditional Medicare."}, "proReasoning": "Policy staff connect totals to the payment rules behind them.", "commonMistake": "Explaining growth without the payment design.", "mentalModel": "Totals hide payment rules."}, "invest": {"call": {"kind": "theCall", "situation": "Regulators study the $84 billion MA gap.", "prompt": "Which driver is easier for rules to target?", "options": ["Favorable selection, by banning choice", "Neither can ever change", "Coding intensity, through risk score rules"], "correctIndex": 2, "consequences": ["Banning choice is not how Medicare works.", "Rules on coding have changed before.", "Payment rules can adjust for extra coding."], "explanation": "Coding can be adjusted through risk score rules. Selection is harder to change."}, "proReasoning": "Investors watch which part of a profit pool rules can reach.", "commonMistake": "Assuming the whole gap is equally at risk.", "mentalModel": "Know which profit rules can reach."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build analytics for MA plans.", "prompt": "Which insight would plans value most now?", "options": ["Where risk scores outrun real costs", "How to sign up more members fast", "How to cut brochure costs"], "correctIndex": 0, "consequences": ["That shows exposure to coding scrutiny.", "Growth does not address the scrutiny.", "Print costs are tiny."], "explanation": "With coding under scrutiny, plans want to know where scores and costs diverge."}, "proReasoning": "Founders build for the risk the buyer worries about this year.", "commonMistake": "Selling growth when the buyer worries about audits.", "mentalModel": "Build for this year's worry."}, "curiosity": {"call": {"kind": "theCall", "situation": "A friend says Medicare Advantage saves the government money.", "prompt": "What did MedPAC estimate for 2025?", "options": ["It costs about half as much", "It costs about 20% more", "It costs exactly the same"], "correctIndex": 1, "consequences": ["MedPAC found higher, not lower, costs.", "About $84 billion more than traditional Medicare.", "MedPAC found a large gap."], "explanation": "MedPAC projected MA would cost about 20% more than traditional Medicare for the same people."}, "proReasoning": "Check who estimated a cost and what they compared it to.", "commonMistake": "Repeating a claim without a source.", "mentalModel": "Check what a cost is compared to."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:01d754b4bb7b$ml$]::text[]),
($ml$bc7ef868-ebb7-57b6-a7ca-3748cc510330$ml$::uuid, $ml$healthtech$ml$, 8, 3, $ml${"id": "healthtech-d8-c3", "title": "A chart review offer", "lessonTitle": "Medicare Advantage costs more", "slot": 3, "type": "decide", "brief": {"headline": "You run compliance at a Medicare Advantage plan. A vendor offers chart reviews that add diagnoses and promises higher payments. Coding intensity added about $40 billion to MA costs in 2025.", "kicker": "Decide: do you sign the vendor?", "fullText": "More recorded diagnoses raise risk scores and payments. Reviews that find real, documented conditions are legitimate.\n\nReviews that only add diagnoses, and never remove unsupported ones, draw scrutiny. Kaiser Permanente affiliates paid $556 million in 2026 to settle allegations about diagnoses added after visits.", "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, Medicare Advantage to cost $84 billion more in 2025"}, {"url": "https://www.justice.gov/opa/pr/kaiser-permanente-affiliates-pay-556m-resolve-false-claims-act-allegations", "label": "US Justice Department, Kaiser Permanente affiliates pay $556M"}]}, "evidence": {"kind": "faceOff", "prompt": "Which review design is safer?", "left": {"name": "Two-way review", "note": "Adds supported codes and removes unsupported ones"}, "right": {"name": "Add-only review", "note": "Finds new codes and never removes any"}, "correctIndex": 0, "explanation": "A two-way review aims at accuracy. An add-only review aims at payments."}, "numbers": {"kind": "numberSense", "prompt": "How many billions was Medicare projected to pay MA plans in 2025?", "min": 0, "max": 800, "value": 538, "unit": "B", "explanation": "About $538 billion."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO likes the vendor's promise of higher payments.", "prompt": "What do you advise?", "options": ["Sign now; more codes mean more pay", "Ban all chart reviews forever", "Require two-way reviews and audits"], "correctIndex": 2, "consequences": ["Add-only reviews invite scrutiny.", "Legitimate reviews can fix real gaps.", "Accuracy protects payments and the plan."], "explanation": "Reviews that add and remove codes aim at accuracy, which regulators accept."}, "proReasoning": "Compliance leaders steer toward accuracy, not toward zero or maximum.", "commonMistake": "Approving a vendor on its revenue promise.", "mentalModel": "Aim for accurate, not maximum."}, "invest": {"call": {"kind": "theCall", "situation": "A plan reports fast revenue growth from chart reviews.", "prompt": "What do you check?", "options": ["Whether reviews also remove codes", "Its member satisfaction score", "Its number of call centers"], "correctIndex": 0, "consequences": ["One-way coding growth carries legal risk.", "Satisfaction says little about coding risk.", "Call centers do not affect coding."], "explanation": "Revenue from add-only reviews may face clawbacks or settlements."}, "proReasoning": "Investors test whether growth would survive an audit.", "commonMistake": "Counting coding revenue as permanent.", "mentalModel": "Test growth against an audit."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could build a chart review product.", "prompt": "Which design wins long-term trust?", "options": ["Skip clinician sign-off", "Flag codes to add and to remove", "Only find codes that raise pay"], "correctIndex": 1, "consequences": ["Clinician review keeps records sound.", "Balanced reviews show you aim at accuracy.", "Add-only designs draw scrutiny."], "explanation": "Balanced reviews are easier to defend to regulators and buyers."}, "proReasoning": "Founders design for the audit, not just the sale.", "commonMistake": "Optimizing for the buyer's revenue over accuracy.", "mentalModel": "Design for the audit."}, "curiosity": {"call": {"kind": "theCall", "situation": "You get a call from your plan to review your conditions.", "prompt": "Why might plans do this?", "options": ["Plans must call every member yearly", "It changes your doctor", "Recorded conditions affect plan payments"], "correctIndex": 2, "consequences": ["No rule requires yearly calls.", "A review does not change your doctor.", "Risk scores built from diagnoses set payments."], "explanation": "Medicare Advantage payments depend on members' recorded conditions."}, "proReasoning": "Ask how a review will be used before sharing details.", "commonMistake": "Thinking a review is only about your care.", "mentalModel": "Reviews can serve payment too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:9a962e5fd9fc$ml$]::text[]),
($ml$17abb031-391b-59c6-a2af-a65d16b1f010$ml$::uuid, $ml$healthtech$ml$, 9, 1, $ml${"id": "healthtech-d9-c1", "title": "A drugstore's doctor bet", "lessonTitle": "The insurer that employs doctors", "slot": 1, "type": "apply", "brief": {"headline": "Walgreens became majority owner of VillageMD, a primary care company, through a $5.2 billion deal in 2021. By June 2024 it planned to cut its stake below a majority.", "kicker": "Apply vertical integration: what if owning doctors does not pay?", "fullText": "VillageMD bought Summit Health-CityMD for $8.9 billion in 2023. That same year, Walgreens said it would close 60 VillageMD sites to cut at least $1 billion in costs.\n\nIn June 2024 Walgreens said it planned to reduce its stake, so it would no longer be the majority owner. Owning doctors is a costly way to integrate.", "sources": [{"url": "https://www.beckersasc.com/asc-transactions-and-valuation-issues/walgreens-closes-more-clinics-reduces-villagemd-stake.html", "label": "Becker's ASC, Walgreens closes more clinics, reduces VillageMD stake"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Walgreens and VillageMD story in order.", "steps": ["Walgreens takes a majority stake for $5.2 billion", "VillageMD buys Summit Health-CityMD", "Walgreens plans to close 60 sites", "Walgreens plans to cut its stake below a majority"], "explanation": "Walgreens bought in, expanded, then cut back as costs grew."}, "numbers": {"kind": "numberSense", "prompt": "How many billions was the 2021 deal that made Walgreens majority owner?", "min": 0, "max": 12, "value": 5.2, "unit": "B", "explanation": "$5.2 billion in 2021."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for strategy at a retailer that wants to own clinics.", "prompt": "What lesson do you bring from Walgreens?", "options": ["Retailers cannot legally own clinics", "Clinics are costly to run and scale", "Clinics always pay off quickly"], "correctIndex": 1, "consequences": ["Walgreens did own a majority stake.", "Walgreens closed sites and cut its stake.", "Walgreens planned closures to cut $1 billion."], "explanation": "Walgreens bought, expanded, then closed sites and cut its stake."}, "proReasoning": "Strategy candidates bring the failure case, not just the success.", "commonMistake": "Assuming integration works because it worked for one rival.", "mentalModel": "Study the failures too."}, "invest": {"call": {"kind": "theCall", "situation": "Walgreens planned to close 60 sites to cut at least $1 billion in costs.", "prompt": "What does that signal about the bet?", "options": ["The clinics grew too profitable", "Closures had no link to costs", "The clinics cost more than expected"], "correctIndex": 2, "consequences": ["Profitable sites are not usually closed.", "Walgreens tied closures to cost cuts.", "Closing sites to save $1 billion shows strain."], "explanation": "Closing sites to cut costs signals the clinics were not paying off as planned."}, "proReasoning": "Investors read closures as a verdict on a strategy.", "commonMistake": "Treating closures as routine housekeeping.", "mentalModel": "Closures are a verdict."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software for primary care groups owned by big companies.", "prompt": "What risk does VillageMD highlight?", "options": ["Owners can shrink or sell clinics fast", "Owners never change strategy", "Primary care demand is disappearing"], "correctIndex": 0, "consequences": ["Walgreens cut sites and its stake within years.", "Walgreens changed course within three years.", "Closures were about costs, not demand."], "explanation": "Corporate owners can change course quickly, which affects their vendors."}, "proReasoning": "Founders diversify customers when owners can change course.", "commonMistake": "Depending on one corporate owner's strategy.", "mentalModel": "Spread risk across owners."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your VillageMD clinic closed near a Walgreens.", "prompt": "What was going on?", "options": ["Patients were banned from it", "Walgreens was cutting costs from its bet", "Clinics must close every few years"], "correctIndex": 1, "consequences": ["Closures were about costs.", "Walgreens planned to close sites to cut costs.", "No rule forces regular closures."], "explanation": "Walgreens closed VillageMD sites as part of cost cuts."}, "proReasoning": "Big owners can close clinics when the numbers do not work.", "commonMistake": "Assuming a clinic closed because of poor care.", "mentalModel": "Owners close sites for costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:b1e451cb1a54$ml$]::text[]),
($ml$bb1785bd-2b76-5e15-80cc-9dc5af85e571$ml$::uuid, $ml$healthtech$ml$, 9, 2, $ml${"id": "healthtech-d9-c2", "title": "Payer, PBM and doctors", "lessonTitle": "The insurer that employs doctors", "slot": 2, "type": "connect", "brief": {"headline": "Day 3 showed UnitedHealth Group's $447.6 billion revenue and its PBM, OptumRx. By late 2023, its Optum unit also had nearly 90,000 employed or affiliated physicians.", "kicker": "Connect day 3 and day 9: one company in more of the chain.", "fullText": "UnitedHealth owns an insurer, a PBM and the largest group of employed doctors in the US. Optum added nearly 20,000 physicians in 2023 alone.\n\nWhen an insurer owns practices, what it pays those doctors stays inside the same company. That can change referrals, pay and how patients move through care.", "sources": [{"url": "https://www.unitedhealthgroup.com/newsroom/2026/2026-01-27-uhg-reports-2025-results-and-issues-2026-outlook.html", "label": "UnitedHealth Group 2025 results"}, {"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum added nearly 20,000 physicians in 2023"}]}, "evidence": {"kind": "sortSignal", "prompt": "Sort each UnitedHealth business by its role.", "buckets": ["Payer", "PBM", "Provider"], "items": [{"text": "UnitedHealthcare", "bucket": 0}, {"text": "OptumRx", "bucket": 1}, {"text": "Optum's employed physicians", "bucket": 2}, {"text": "UnitedHealthcare's Medicare plans", "bucket": 0}], "explanation": "UnitedHealth sits on the payer, PBM and provider sides at once."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand physicians did Optum have by late 2023?", "min": 0, "max": 150, "value": 90, "unit": "K", "explanation": "Nearly 90,000 employed or affiliated physicians."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview at Optum. They ask why UnitedHealth employs doctors.", "prompt": "What is the sharpest answer?", "options": ["Because insurers must employ doctors", "To sell more drugs in stores", "To keep more of the care dollar inside"], "correctIndex": 2, "consequences": ["No rule requires insurers to employ doctors.", "Optum doctors deliver care, not retail.", "Payments to its doctors stay inside the company."], "explanation": "Owning practices keeps payments to doctors inside UnitedHealth."}, "proReasoning": "Strong candidates explain why the money stays in the building.", "commonMistake": "Describing size without the money flow.", "mentalModel": "Follow the money inside the company."}, "invest": {"call": {"kind": "theCall", "situation": "UnitedHealth owns a payer, a PBM and nearly 90,000 physicians.", "prompt": "What risk grows with that reach?", "options": ["Scrutiny over referrals and competition", "Too few patients to serve each year", "Falling demand for doctors"], "correctIndex": 0, "consequences": ["Owning more of the chain draws regulators.", "It serves tens of millions of people.", "Doctor demand is not falling."], "explanation": "An insurer that owns doctors and a PBM draws questions about steering and competition."}, "proReasoning": "Investors weigh integration gains against regulatory reach.", "commonMistake": "Ignoring how scale invites scrutiny.", "mentalModel": "Scale invites scrutiny."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your referral app helps independent doctors.", "prompt": "What pitch fits a market with Optum in it?", "options": ["Replace insurers entirely", "Help independents keep referrals local", "Help Optum hire more doctors faster"], "correctIndex": 1, "consequences": ["That is a different business.", "Independents worry about patients flowing inside Optum.", "Optum is not your buyer here."], "explanation": "Insurer-owned practices can change how patients flow. Independents need help competing."}, "proReasoning": "Founders serve whoever is squeezed by a big player.", "commonMistake": "Building for the giant instead of those it squeezes.", "mentalModel": "Serve whoever is squeezed."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your doctor's practice was bought by Optum.", "prompt": "What does that mean?", "options": ["Your doctor works for a drugstore", "Nothing about ownership changed", "Your insurer's parent may now own it"], "correctIndex": 2, "consequences": ["Optum is not a drugstore chain.", "Ownership did change.", "Optum is part of UnitedHealth Group."], "explanation": "Optum is UnitedHealth's care unit, so the insurer's parent may own your practice."}, "proReasoning": "Ask who owns your doctor's practice and your insurer.", "commonMistake": "Assuming your doctor is independent.", "mentalModel": "Your doctor may share an owner with your insurer."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:cc64ee8c4b79$ml$]::text[]),
($ml$856f4a32-c4e4-541b-9914-c56eb5dfc625$ml$::uuid, $ml$healthtech$ml$, 9, 3, $ml${"id": "healthtech-d9-c3", "title": "Selling the practice", "lessonTitle": "The insurer that employs doctors", "slot": 3, "type": "decide", "brief": {"headline": "You own an independent 12-doctor practice. An insurer-owned company offers to buy it. Optum added nearly 20,000 physicians in 2023.", "kicker": "Decide: what do you weigh first?", "fullText": "Selling brings cash, support and stable pay. It can also change where you refer patients, how you are paid and who sets your rules.\n\nInsurer ownership can change referrals, pay and how patients flow. You must decide what matters most before you sign.", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum added nearly 20,000 physicians in 2023"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What should you weigh first?", "options": ["Control over referrals and care choices", "The color of the new signs out front", "The new email address format"], "correctIndex": 0, "explanation": "Insurer ownership can change referrals and pay. That shapes daily practice."}, "numbers": {"kind": "numberSense", "prompt": "About how many thousand doctors did Optum add in 2023?", "min": 0, "max": 50, "value": 20, "unit": "K", "explanation": "Nearly 20,000 in a single year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You manage the practice. The doctors ask what to negotiate.", "prompt": "What matters most?", "options": ["Clear terms on referrals and pay", "Free parking for all staff", "A larger break room"], "correctIndex": 0, "consequences": ["These shape care and income after the sale.", "Parking is minor next to pay terms.", "A break room does not shape care."], "explanation": "Ownership terms on referrals and pay shape the practice for years."}, "proReasoning": "Practice managers negotiate what changes daily work.", "commonMistake": "Focusing on perks over control.", "mentalModel": "Negotiate control, not perks."}, "invest": {"call": {"kind": "theCall", "situation": "You advise a practice weighing the offer.", "prompt": "How do you value staying independent?", "options": ["Always reject insurer offers", "Weigh control against stable pay", "Independence has no value"], "correctIndex": 1, "consequences": ["Some offers may fit the practice.", "Both sides have real worth.", "Control over care has value."], "explanation": "The choice trades control for stability. Both have value."}, "proReasoning": "Advisers price what the seller gives up, not just what they get.", "commonMistake": "Looking only at the purchase price.", "mentalModel": "Price what you give up."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build tools for independent practices.", "prompt": "What does Optum's growth mean for you?", "options": ["Your market is growing fast every year", "Insurers will buy your tool", "Fewer independents, so serve them well"], "correctIndex": 2, "consequences": ["Independents are being bought.", "Owners may bring their own tools.", "Every acquisition shrinks your buyer pool."], "explanation": "As practices are bought, the pool of independent buyers shrinks."}, "proReasoning": "Founders track whether their buyer pool is growing or shrinking.", "commonMistake": "Ignoring consolidation in your market.", "mentalModel": "Watch your buyer pool."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear doctors are selling practices to insurers.", "prompt": "Why might doctors sell?", "options": ["For cash, support and stable pay", "Because a law forces them", "Because patients asked them to"], "correctIndex": 0, "consequences": ["These are the main draws of selling.", "No law forces the sale.", "Patients are rarely asked."], "explanation": "Selling brings money and support, but can change referrals and pay."}, "proReasoning": "Ask your doctor who owns the practice now.", "commonMistake": "Assuming doctors sell only for money.", "mentalModel": "Selling trades control for support."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:450a202a6328$ml$]::text[]),
($ml$be3b6bb7-caf7-5a1f-a89b-289a114626e8$ml$::uuid, $ml$healthtech$ml$, 10, 1, $ml${"id": "healthtech-d10-c1", "title": "California fills part of the gap", "lessonTitle": "When subsidies expired", "slot": 1, "type": "apply", "brief": {"headline": "When enhanced federal subsidies expired, Covered California used $190 million in state subsidies. Renewals rose 4%, but new sign-ups fell 32%.", "kicker": "Apply the subsidy lesson: what happens when a state steps in?", "fullText": "California's state subsidies helped 389,590 people, with an average of $45 a month, for those up to 165% of the federal poverty level. Renewals reached 1,692,316. New sign-ups fell to 235,055 from 345,711.\n\nMore than 130,000 renewing enrollees switched to Bronze plans. More than 1 in 3 new enrollees picked Bronze, up from fewer than 1 in 4 in 2025.", "sources": [{"url": "https://www.coveredca.com/press-releases/2026/02/26/as-enhanced-federal-subsidies-expire-covered-california-ends-open-enrollment-with-state-subsidies-keeping-renewals-steady-for-now-and-new-signups-down", "label": "Covered California, open enrollment results 2026"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["Covered California renewals rose 4%.", "New sign-ups rose after subsidies expired.", "More than 130,000 renewing enrollees moved to Bronze."], "fakeIndex": 1, "explanation": "New sign-ups fell 32%, from 345,711 to 235,055."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did new Covered California sign-ups fall?", "min": 0, "max": 80, "value": 32, "unit": "%", "explanation": "Down 32%, from 345,711 to 235,055."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in outreach at a state Marketplace after subsidies drop.", "prompt": "Which group do you focus on?", "options": ["Renewing members, whose numbers rose 4%", "People already on Medicare", "New shoppers, where sign-ups fell most"], "correctIndex": 2, "consequences": ["Renewals held up with state help.", "Medicare members do not use the Marketplace.", "New sign-ups fell 32% in California."], "explanation": "California held renewals steady, but lost about a third of new sign-ups."}, "proReasoning": "Outreach teams aim where the numbers fell most.", "commonMistake": "Spreading effort evenly when one group fell sharply.", "mentalModel": "Aim where the drop is biggest."}, "invest": {"call": {"kind": "theCall", "situation": "You cover an insurer selling plans in California.", "prompt": "What shift in its plan mix should you expect?", "options": ["More Bronze plans, with lower premiums", "More Gold plans, with higher premiums", "No change in plan choices"], "correctIndex": 0, "consequences": ["Over 130,000 renewing members moved to Bronze.", "Members moved down, not up.", "Bronze share rose for new enrollees."], "explanation": "Higher costs pushed people toward cheaper Bronze plans."}, "proReasoning": "Investors watch plan mix when prices change.", "commonMistake": "Assuming members stay in the same plans.", "mentalModel": "Price changes move plan mix."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a plan-picking tool for Marketplace shoppers.", "prompt": "Which feature matters most now?", "options": ["Hide state subsidies from users", "Show Bronze trade-offs on deductibles", "Show only the priciest plans"], "correctIndex": 1, "consequences": ["Subsidies are what make plans affordable.", "Many are moving to Bronze and need the trade-offs.", "Shoppers are moving to cheaper plans."], "explanation": "Bronze has lower premiums but higher costs when care is used."}, "proReasoning": "Founders help users with the choice they are making right now.", "commonMistake": "Building for last year's choices.", "mentalModel": "Help with today's choice."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your friend in California kept their plan but switched to Bronze.", "prompt": "What is the likely reason?", "options": ["Bronze plans cover more care", "Bronze became free for everyone", "Lower premiums after subsidies fell"], "correctIndex": 2, "consequences": ["Bronze usually has higher out-of-pocket costs.", "Bronze still has premiums for most.", "Over 130,000 renewing members did the same."], "explanation": "With less help, many moved to Bronze for lower monthly premiums."}, "proReasoning": "Compare deductibles too, not just premiums.", "commonMistake": "Picking a plan on the monthly price alone.", "mentalModel": "Look past the monthly price."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:55a5e25a9bd4$ml$]::text[]),
($ml$426cf25f-5d30-505f-91b8-68e713612b98$ml$::uuid, $ml$healthtech$ml$, 10, 2, $ml${"id": "healthtech-d10-c2", "title": "From subsidies to the uninsured", "lessonTitle": "When subsidies expired", "slot": 2, "type": "connect", "brief": {"headline": "Day 4 showed 26.7 million people had no insurance for all of 2025. After enhanced subsidies expired, paid Marketplace enrollment fell from 22.1 million to 19.2 million by February 2026.", "kicker": "Connect day 4 and day 10: when help shrinks, coverage can fall.", "fullText": "Premium tax credits lower what Marketplace enrollees pay each month. KFF estimated that without the enhanced credits, subsidized enrollees' payments would rise 114% on average, from $888 to $1,904 a year.\n\nPaid enrollment fell about 13%. People who drop coverage may join the uninsured counted on day 4.", "sources": [{"url": "https://www.census.gov/library/publications/2026/demo/p60-291.html", "label": "US Census, health insurance coverage 2025"}, {"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, premium payments would more than double if enhanced credits expire"}, {"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, Marketplace enrollment down by 3 million"}]}, "evidence": {"kind": "buildChain", "prompt": "Order how expiring subsidies can affect coverage.", "steps": ["Enhanced tax credits expire", "Enrollees' premium payments rise", "Some enrollees drop coverage", "Paid enrollment falls", "More people may be uninsured"], "explanation": "Less help means higher payments, and some people stop paying for coverage."}, "numbers": {"kind": "numberSense", "prompt": "How many million people had paid Marketplace coverage by February 2026?", "min": 0, "max": 30, "value": 19.2, "unit": "M", "explanation": "About 19.2 million, down from 22.1 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work at a community health center after subsidies expire.", "prompt": "What should you prepare for?", "options": ["More patients without coverage", "Fewer patients needing care", "Insurers paying more per visit"], "correctIndex": 0, "consequences": ["Enrollment fell 13%, so more may be uninsured.", "Needs do not drop when coverage does.", "Subsidy loss does not raise insurer rates."], "explanation": "When Marketplace enrollment falls, more patients may arrive without insurance."}, "proReasoning": "Clinic leaders plan for shifts in who pays.", "commonMistake": "Assuming patient volume and coverage move together.", "mentalModel": "Coverage can fall while needs stay."}, "invest": {"call": {"kind": "theCall", "situation": "Paid Marketplace enrollment fell 13% in early 2026.", "prompt": "Which providers feel it most?", "options": ["Dentists with cash-paying patients", "Hospitals with many Marketplace patients", "Clinics serving only Medicare"], "correctIndex": 1, "consequences": ["Cash patients are not on the Marketplace.", "They may see more unpaid care.", "Medicare members are not affected."], "explanation": "Providers that relied on Marketplace patients may see more unpaid care."}, "proReasoning": "Investors trace a policy change to the providers most exposed.", "commonMistake": "Treating a coverage drop as an insurer-only issue.", "mentalModel": "Coverage shifts reach providers."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app helps people find coverage they qualify for.", "prompt": "Where is demand rising?", "options": ["People with stable job coverage", "People already on Medicare", "People who just lost subsidized plans"], "correctIndex": 2, "consequences": ["They have coverage already.", "They are covered by Medicare.", "About 3 million fewer people paid for plans."], "explanation": "Millions left Marketplace plans and may qualify for other help."}, "proReasoning": "Founders move toward people a policy change just affected.", "commonMistake": "Targeting people whose coverage did not change.", "mentalModel": "Go where policy just changed lives."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that 3 million fewer people paid for Marketplace plans.", "prompt": "What is the main cause?", "options": ["Enhanced subsidies expired", "Plans got much cheaper", "Everyone moved to jobs with coverage"], "correctIndex": 0, "consequences": ["Premium payments rose for many enrollees.", "Payments rose, not fell.", "There is no sign of that."], "explanation": "After enhanced credits expired, many enrollees faced much higher payments."}, "proReasoning": "Look for the policy change behind a big shift.", "commonMistake": "Assuming people left because they no longer needed coverage.", "mentalModel": "Find the policy behind the shift."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:d550bcfc55e1$ml$]::text[]),
($ml$6914f37d-3934-5657-9b86-0a885c1e4cf4$ml$::uuid, $ml$healthtech$ml$, 10, 3, $ml${"id": "healthtech-d10-c3", "title": "Renewal season after the cliff", "lessonTitle": "When subsidies expired", "slot": 3, "type": "decide", "brief": {"headline": "You run member renewals at a Marketplace insurer. KFF estimated subsidized enrollees' payments would rise 114% on average without the enhanced credits.", "kicker": "Decide: how do you keep members covered?", "fullText": "Many members face much higher monthly payments. Some will drop coverage, and some will look for cheaper plans.\n\nYou can let them leave, raise outreach, or show them lower-premium options such as Bronze. Effectuated enrollment counts only people who actually pay.", "sources": [{"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, premium payments would more than double if enhanced credits expire"}, {"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, Marketplace enrollment down by 3 million"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What keeps the most members covered?", "options": ["Send one renewal letter and then wait", "Raise premiums to cover losses", "Show lower-premium options before renewal"], "correctIndex": 2, "explanation": "Many members moved to Bronze. Showing them options early keeps them paying."}, "numbers": {"kind": "numberSense", "prompt": "By what percent did KFF estimate subsidized enrollees' payments would rise?", "min": 0, "max": 200, "value": 114, "unit": "%", "explanation": "About 114%, from $888 to $1,904 a year on average."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your boss asks for one renewal tactic.", "prompt": "Which do you pick?", "options": ["Offer a free tote bag", "Call members with cheaper plan options", "Wait for members to call you first"], "correctIndex": 1, "consequences": ["A gift does not offset a 114% rise.", "Early options keep members from dropping.", "Many will drop before calling."], "explanation": "Members facing big increases need options before they drop out."}, "proReasoning": "Retention teams act before the bill arrives.", "commonMistake": "Waiting for members to ask.", "mentalModel": "Act before the bill arrives."}, "invest": {"call": {"kind": "theCall", "situation": "A Marketplace insurer says its paid enrollment held steady.", "prompt": "What do you check?", "options": ["Plan selections at sign-up only", "How many ads it ran", "Effectuated, paid enrollment numbers"], "correctIndex": 2, "consequences": ["Selections can drop when bills arrive.", "Ads do not show who paid.", "Only paid members bring revenue."], "explanation": "Effectuated enrollment counts people who actually paid."}, "proReasoning": "Investors use paid enrollment, not sign-ups.", "commonMistake": "Trusting sign-up totals over paid members.", "mentalModel": "Count who actually pays."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could build a renewal tool for Marketplace insurers.", "prompt": "Which feature matters most?", "options": ["Flag members at risk of not paying", "Design nicer welcome emails", "Track members' favorite colors"], "correctIndex": 0, "consequences": ["Insurers can reach them before coverage ends.", "Emails do not find who will drop.", "Irrelevant to retention."], "explanation": "Insurers need to find members likely to drop before they stop paying."}, "proReasoning": "Founders build early warnings where losses are costly.", "commonMistake": "Building polish instead of early warning.", "mentalModel": "Warn early where losses cost most."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your renewal notice shows a much higher monthly payment.", "prompt": "Why could that be?", "options": ["Your plan added free gym visits", "Enhanced tax credits expired", "Your doctor raised prices"], "correctIndex": 1, "consequences": ["Perks do not explain a big jump.", "That raised payments for many enrollees.", "Doctor prices do not set your premium share."], "explanation": "When enhanced credits expired, many enrollees' payments rose sharply."}, "proReasoning": "Compare other plans before renewing automatically.", "commonMistake": "Renewing without checking other options.", "mentalModel": "Compare before you renew."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:76f811ca4e8a$ml$]::text[]),
($ml$7a7516ca-492b-54a7-a90b-6ebb85451df7$ml$::uuid, $ml$healthtech$ml$, 11, 1, $ml${"id": "healthtech-d11-c1", "title": "Round two: Ozempic at 71% off", "lessonTitle": "Medicare negotiates drug prices", "slot": 1, "type": "apply", "brief": {"headline": "On November 26, 2025, CMS announced negotiated prices for 15 more drugs, starting January 1, 2027. Ozempic and Wegovy got a 71% discount.", "kicker": "Apply negotiation: what did the second round change?", "fullText": "Discounts in the second round ranged from 38% for Austedo to 85% for Janumet. The negotiated price for Ozempic and Wegovy is $274 for a 30-day supply.\n\nCMS estimated the new prices would save Medicare about $12 billion and patients about $685 million out of pocket. The first round covered 10 drugs and took effect in January 2026.", "sources": [{"url": "https://www.managedhealthcareexecutive.com/view/cms-negotiates-a-70-discount-for-ozempic-and-wegovy", "label": "Managed Healthcare Executive, CMS negotiates a 71% discount for Ozempic and Wegovy"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The second round covers 15 drugs.", "The new prices take effect in January 2026.", "Janumet got the deepest discount, 85%."], "fakeIndex": 1, "explanation": "The second-round prices start January 1, 2027. The first round started in January 2026."}, "numbers": {"kind": "numberSense", "prompt": "What discount did CMS negotiate for Ozempic and Wegovy?", "min": 0, "max": 100, "value": 71, "unit": "%", "explanation": "71%, for a price of $274 for a 30-day supply."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a Medicare drug plan as an analyst in 2026.", "prompt": "What should you plan for in 2027?", "options": ["Lower prices on 15 more drugs", "All drug prices doubling", "Medicare ending drug coverage"], "correctIndex": 0, "consequences": ["Second-round prices start January 1, 2027.", "Negotiation lowers prices, not raises them.", "Medicare drug coverage continues."], "explanation": "Fifteen more negotiated prices take effect in 2027."}, "proReasoning": "Plan analysts track which prices change and when.", "commonMistake": "Treating negotiation as a one-time event.", "mentalModel": "Negotiation now comes in rounds."}, "invest": {"call": {"kind": "theCall", "situation": "You own shares in a maker of one of the 15 drugs.", "prompt": "What do you model for 2027?", "options": ["No change from negotiation", "Lower Medicare revenue per prescription", "Higher Medicare prices for its drug"], "correctIndex": 1, "consequences": ["The new prices apply from 2027.", "Discounts ran from 38% to 85%.", "Negotiated prices are discounts."], "explanation": "A negotiated price cuts what Medicare pays for each prescription."}, "proReasoning": "Investors model the discount, then any change in volume.", "commonMistake": "Ignoring negotiation in a drugmaker's Medicare forecast.", "mentalModel": "Model the discount first."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your app helps Medicare patients compare drug costs.", "prompt": "What update matters most for 2027?", "options": ["Remove Medicare drugs entirely", "Show only list prices", "Add the 15 new negotiated prices"], "correctIndex": 2, "consequences": ["Medicare users need Medicare drugs.", "List prices miss the negotiated price.", "Users need the new prices to compare plans."], "explanation": "Fifteen drugs get new prices in 2027, which changes what users pay."}, "proReasoning": "Founders update data as soon as a rule changes prices.", "commonMistake": "Letting price data go stale after a rule change.", "mentalModel": "Update when rules change prices."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that Medicare negotiated 71% off Ozempic.", "prompt": "Who does that price apply to?", "options": ["Medicare, from January 2027", "Every buyer in the US now", "Only buyers outside the US"], "correctIndex": 0, "consequences": ["It is a Medicare price starting in 2027.", "Negotiated prices are for Medicare.", "It is a US Medicare price."], "explanation": "The negotiated price applies in Medicare, starting January 1, 2027."}, "proReasoning": "Check who a price applies to and when it starts.", "commonMistake": "Assuming a Medicare price applies to everyone.", "mentalModel": "Check who a price is for."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:baac89aec21d$ml$]::text[]),
($ml$64c9be61-acc0-58f5-ae90-15e13939aa00$ml$::uuid, $ml$healthtech$ml$, 11, 2, $ml${"id": "healthtech-d11-c2", "title": "Why drugs were a target", "lessonTitle": "Medicare negotiates drug prices", "slot": 2, "type": "connect", "brief": {"headline": "Day 2 showed the US spent $1,635 per person on drugs, against $944 in peer countries. Medicare negotiation targets that gap for its own costliest drugs.", "kicker": "Connect day 2 and day 11: high prices led to negotiation.", "fullText": "The 2022 Inflation Reduction Act let Medicare negotiate prices for some high-cost drugs. The first 10 prices, for drugs such as Eliquis, Jardiance and Stelara, took effect on January 1, 2026.\n\nCMS estimated the prices would have saved Medicare about $6 billion, or 22%, in the prior year. Patients were expected to save about $1.5 billion out of pocket in 2026.", "sources": [{"url": "https://www.kff.org/health-costs/what-drives-health-spending-in-the-u-s-compared-to-other-countries/", "label": "KFF, US health spending vs other countries"}, {"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated prices would have saved Medicare $6B"}]}, "evidence": {"kind": "faceOff", "prompt": "Who spent more per person on drugs, per KFF?", "left": {"name": "The United States", "note": "$1,635 per person"}, "right": {"name": "Peer countries", "note": "$944 per person on average"}, "correctIndex": 0, "explanation": "The US spent about $700 more per person on drugs than peer countries."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand dollars per person did the US spend on drugs?", "min": 0, "max": 3, "value": 1.6, "unit": "K", "explanation": "$1,635 per person, against $944 in peer countries."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "A policy interviewer asks why Congress let Medicare negotiate.", "prompt": "Which point connects day 2 and day 11?", "options": ["Peer countries pay more for drugs", "US drug spending far outpaces peers", "Drugs are a tiny share of costs"], "correctIndex": 1, "consequences": ["Peers paid less, not more.", "$1,635 against $944 per person.", "Drugs are a large and growing line."], "explanation": "High US drug spending set up the case for negotiation."}, "proReasoning": "Policy answers link a rule to the number it targets.", "commonMistake": "Explaining a law without the problem it addresses.", "mentalModel": "Link the rule to its number."}, "invest": {"call": {"kind": "theCall", "situation": "You compare drugmakers by how much of their sales come from Medicare.", "prompt": "Why does that matter now?", "options": ["Medicare stopped buying drugs", "Medicare pays above list prices for drugs", "Medicare can negotiate its costliest drugs"], "correctIndex": 2, "consequences": ["Medicare still covers drugs.", "Negotiated prices are discounts.", "Negotiation cuts prices on selected drugs."], "explanation": "Drugmakers with big Medicare sales on costly drugs face negotiation."}, "proReasoning": "Investors map exposure to a rule before it reaches a company.", "commonMistake": "Treating all drug revenue as equally safe.", "mentalModel": "Map exposure before the rule hits."}, "build_startup": {"call": {"kind": "theCall", "situation": "You help employers lower drug costs.", "prompt": "What does Medicare negotiation show your buyers?", "options": ["Big buyers can win deep discounts", "Drug prices cannot change", "Discounts only exist abroad"], "correctIndex": 0, "consequences": ["Medicare won 38% to 79% off in round one.", "Negotiation did change prices.", "Medicare is a US buyer."], "explanation": "Large buyers can push prices down, which supports group purchasing."}, "proReasoning": "Founders use big public wins as proof for their pitch.", "commonMistake": "Pitching savings without a real example.", "mentalModel": "Use public wins as proof."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why US drug costs are a political topic.", "prompt": "What is the core number?", "options": ["The same as every other country", "$1,635 per person, versus $944 abroad", "$100 per person, the lowest anywhere"], "correctIndex": 1, "consequences": ["The US spends much more.", "The US spends far more per person.", "US drug spending is the highest, not lowest."], "explanation": "Americans spend far more per person on drugs than people in peer countries."}, "proReasoning": "Compare with peers to see if a cost is unusual.", "commonMistake": "Judging a cost without a comparison.", "mentalModel": "Compare with peers."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:276366440c05$ml$]::text[]),
($ml$5bd8f271-7fc7-5682-a9ea-187ec16a6186$ml$::uuid, $ml$healthtech$ml$, 11, 3, $ml${"id": "healthtech-d11-c3", "title": "When your drug is picked", "lessonTitle": "Medicare negotiates drug prices", "slot": 3, "type": "decide", "brief": {"headline": "You run strategy at a drugmaker. Your top drug could be chosen for Medicare negotiation. In round one, discounts on 10 drugs ran from 38% to 79% off list.", "kicker": "Decide: how do you plan for negotiation?", "fullText": "Medicare picks high-cost drugs for negotiation. A negotiated price can cut what Medicare pays per prescription by a large share.\n\nYou can ignore the risk, plan for a lower Medicare price, or shift investment to other drugs. Your forecast and pipeline depend on the choice.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated prices would have saved Medicare $6B"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What should your forecast assume?", "options": ["Negotiation never affects sales", "A lower Medicare price if selected", "Medicare prices always rise"], "correctIndex": 1, "explanation": "Selected drugs got 38% to 79% off list in round one."}, "numbers": {"kind": "numberSense", "prompt": "What share did CMS estimate negotiated prices would have saved Medicare?", "min": 0, "max": 50, "value": 22, "unit": "%", "explanation": "About 22%, or $6 billion, based on the prior year."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks how to brief the board on negotiation risk.", "prompt": "What do you show?", "options": ["Only the best-case forecast", "A list of competitors' logos", "Revenue under a negotiated price"], "correctIndex": 2, "consequences": ["It hides a known risk.", "Logos say nothing about risk.", "The board sees the real downside."], "explanation": "Showing revenue under a negotiated price makes the risk concrete."}, "proReasoning": "Strategy staff show the downside case, not just the plan.", "commonMistake": "Presenting only the forecast that ignores the rule.", "mentalModel": "Show the downside case."}, "invest": {"call": {"kind": "theCall", "situation": "A drugmaker's forecast ignores Medicare negotiation.", "prompt": "How do you react?", "options": ["Discount the forecast for the risk", "Trust it; the law is temporary", "Raise your price target"], "correctIndex": 0, "consequences": ["Selected drugs face large discounts.", "The law has already set prices twice.", "Ignored risk is not upside."], "explanation": "Negotiation has set prices in two rounds. A forecast should reflect it."}, "proReasoning": "Investors adjust forecasts that skip known rules.", "commonMistake": "Accepting a forecast that ignores a working law.", "mentalModel": "Adjust for known rules."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build forecasting tools for drugmakers.", "prompt": "Which feature fits this moment?", "options": ["Design product logos", "Model revenue under negotiated prices", "Track social media likes for each drug"], "correctIndex": 1, "consequences": ["Logos are not forecasts.", "Buyers need to see the effect of a discount.", "Likes do not forecast revenue."], "explanation": "Drugmakers need to model what negotiation does to revenue."}, "proReasoning": "Founders build for the new question a rule creates.", "commonMistake": "Ignoring the rule your buyer worries about most.", "mentalModel": "Build for the new question."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear drugmakers worry about Medicare negotiation.", "prompt": "Why does it matter so much to them?", "options": ["It raises their prices", "It only affects cheap generic drugs", "It can cut Medicare prices sharply"], "correctIndex": 2, "consequences": ["Negotiation lowers prices.", "It targets costly brand drugs.", "Discounts ran from 38% to 79% in round one."], "explanation": "Negotiation can sharply cut what Medicare pays for a selected drug."}, "proReasoning": "Follow who loses revenue to see who pushes back on a rule.", "commonMistake": "Assuming a price rule affects everyone equally.", "mentalModel": "Follow who loses revenue."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:1c74bab4fd75$ml$]::text[]),
($ml$c5c4a334-6b15-550d-b8bb-54bca8269b20$ml$::uuid, $ml$healthtech$ml$, 12, 1, $ml${"id": "healthtech-d12-c1", "title": "An algorithm in court", "lessonTitle": "AI decides prior authorization", "slot": 1, "type": "apply", "brief": {"headline": "In February 2025, a federal judge let parts of a lawsuit against UnitedHealthcare move forward. The suit alleges an algorithm, nH Predict, drove denials of post-acute care.", "kicker": "Apply the AI lesson: who answers for an algorithm's decisions?", "fullText": "Judge John Tunheim in Minnesota allowed the breach of contract and good faith claims to proceed. He dismissed other claims, including unjust enrichment, as preempted by the Medicare Act.\n\nThe plaintiffs, who sued in November 2023, allege that over 90% of the denials are reversed on appeal. These are allegations. UnitedHealthcare disputes the claims.", "sources": [{"url": "https://www.govinfosecurity.com/court-unitedhealth-must-answer-for-ai-based-claim-denials-a-27534", "label": "GovInfoSecurity, UnitedHealth must answer for AI-based claim denials"}]}, "evidence": {"kind": "sortSignal", "prompt": "What happened to each claim?", "buckets": ["Moves forward", "Dismissed"], "items": [{"text": "Breach of contract", "bucket": 0}, {"text": "Breach of good faith and fair dealing", "bucket": 0}, {"text": "Unjust enrichment", "bucket": 1}, {"text": "State law claims preempted by the Medicare Act", "bucket": 1}], "explanation": "Contract and good faith claims survived. Others were dismissed as preempted."}, "numbers": {"kind": "numberSense", "prompt": "Plaintiffs allege what share of appealed denials are reversed?", "min": 0, "max": 100, "value": 90, "unit": "%", "explanation": "Over 90%, according to the plaintiffs. UnitedHealthcare disputes the claims."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a health plan's team that uses software to review claims.", "prompt": "What safeguard do you push for?", "options": ["Hide how decisions are made", "A human reviews each denial", "Let the model decide alone"], "correctIndex": 1, "consequences": ["Hidden logic invites legal challenges.", "Human review guards against wrong denials.", "That is what the lawsuit alleges went wrong."], "explanation": "The lawsuit centers on whether software drove denials. Human review is the key check."}, "proReasoning": "Teams using AI build in human checks before decisions are final.", "commonMistake": "Trusting a model's output as the final word.", "mentalModel": "Keep a human on denials."}, "invest": {"call": {"kind": "theCall", "situation": "You hold shares in an insurer using AI to review claims.", "prompt": "What does the ruling signal?", "options": ["AI decisions are always safe", "The case was fully dismissed", "AI denials can bring legal risk"], "correctIndex": 2, "consequences": ["The suit shows they can be challenged.", "Two claims survived.", "Some claims against UHC are moving forward."], "explanation": "The case continues on contract claims, so AI use carries legal exposure."}, "proReasoning": "Investors price legal risk from how a company uses AI.", "commonMistake": "Assuming automation cuts cost with no risk.", "mentalModel": "AI savings can carry legal costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell AI claim review software to insurers.", "prompt": "What should your product show buyers?", "options": ["Clear reasons and human sign-off", "Faster denials with no review", "Hidden scoring buyers cannot see"], "correctIndex": 0, "consequences": ["Buyers need to defend decisions in court.", "Speed without review is the risk alleged here.", "Opaque scores are hard to defend."], "explanation": "Buyers face lawsuits over AI denials, so they need explainable, reviewed decisions."}, "proReasoning": "Founders sell defensibility, not just speed.", "commonMistake": "Selling automation that buyers cannot explain.", "mentalModel": "Sell decisions buyers can defend."}, "curiosity": {"call": {"kind": "theCall", "situation": "You read that an insurer is being sued over an algorithm.", "prompt": "What is the claim about?", "options": ["Doctors writing the claims software", "Software allegedly driving care denials", "The insurer refusing all claims"], "correctIndex": 1, "consequences": ["The software is the insurer's tool.", "Plaintiffs allege nH Predict set care limits.", "The suit is about post-acute care denials."], "explanation": "Plaintiffs allege an algorithm drove denials of post-acute care. UHC disputes it."}, "proReasoning": "Separate what plaintiffs allege from what a court has found.", "commonMistake": "Treating allegations as proven facts.", "mentalModel": "Allegations are not findings."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:5c92417f34ac$ml$]::text[]),
($ml$a060292d-fe76-5c26-89ed-0248589e50dc$ml$::uuid, $ml$healthtech$ml$, 12, 2, $ml${"id": "healthtech-d12-c2", "title": "Paid for savings, again", "lessonTitle": "AI decides prior authorization", "slot": 2, "type": "connect", "brief": {"headline": "Day 7 showed ACOs sharing savings when costs come in low. In WISeR, the AI prior authorization test that began January 1, 2026, vendors also earn more when spending falls.", "kicker": "Connect day 7 and day 12: paying for savings cuts both ways.", "fullText": "Medicare ACOs saved a record $2.4 billion in 2024 while improving several quality measures. WISeR runs for six years in six states and pays vendors partly on savings.\n\nThe American Hospital Association warned that paying for savings could push denials. WISeR requires a human clinician to review any denial before it is final.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, MSSP ACOs saved $2.4B in 2024"}, {"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, "evidence": {"kind": "buildChain", "prompt": "Order a WISeR prior authorization request.", "steps": ["A provider requests approval for a service", "AI technology reviews the request", "The request is flagged for possible denial", "A human clinician reviews the denial", "A final decision is made"], "explanation": "A human clinician reviews any denial before it becomes final."}, "numbers": {"kind": "numberSense", "prompt": "How many years does the WISeR test run?", "min": 0, "max": 10, "value": 6, "unit": "years", "explanation": "Six years, starting January 1, 2026."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You brief a hospital board on WISeR.", "prompt": "Which risk do you link to day 7?", "options": ["Vendors get paid per approval", "Hospitals keep the savings", "Savings pay can reward denials"], "correctIndex": 2, "consequences": ["Vendors earn more when spending falls.", "Savings go to the vendors and Medicare.", "The AHA warned of exactly this."], "explanation": "Like ACOs, WISeR vendors gain when spending falls. That can reward denials."}, "proReasoning": "Link a new model to an old one with the same incentive.", "commonMistake": "Assuming savings pay always means better care.", "mentalModel": "Same incentive, different risks."}, "invest": {"call": {"kind": "theCall", "situation": "You value a vendor in WISeR paid on savings.", "prompt": "What drives its revenue?", "options": ["How much spending falls", "How many requests it approves", "How many hospitals it owns"], "correctIndex": 0, "consequences": ["Vendors earn more when spending falls.", "Approvals do not raise its pay.", "Vendors do not own hospitals."], "explanation": "WISeR pays vendors partly on savings, so revenue tracks lower spending."}, "proReasoning": "Investors tie revenue to the metric a contract rewards.", "commonMistake": "Valuing a vendor on volume when it is paid on savings.", "mentalModel": "Revenue follows the reward metric."}, "build_startup": {"call": {"kind": "theCall", "situation": "You design prior authorization AI for a WISeR vendor.", "prompt": "Which feature protects patients and the vendor?", "options": ["Skip records to move faster", "Route every denial to a clinician", "Auto-deny anything unclear"], "correctIndex": 1, "consequences": ["Missing records means wrong decisions.", "WISeR requires human review of denials.", "That invites the denials the AHA feared."], "explanation": "WISeR requires a human clinician to review denials before they are final."}, "proReasoning": "Founders build the required safeguard into the product.", "commonMistake": "Treating the safeguard as someone else's job.", "mentalModel": "Build the safeguard in."}, "curiosity": {"call": {"kind": "theCall", "situation": "You hear AI now reviews some Medicare requests.", "prompt": "Who makes the final call on a denial?", "options": ["The AI alone", "The patient", "A human clinician"], "correctIndex": 2, "consequences": ["Denials are not final without human review.", "Patients can appeal, but do not decide.", "WISeR requires clinician review of denials."], "explanation": "Under WISeR, a human clinician reviews any denial before it is final."}, "proReasoning": "Ask who reviews an automated decision.", "commonMistake": "Assuming AI makes final care decisions.", "mentalModel": "Ask who has the final say."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8ddd756dd3e2$ml$]::text[]),
($ml$98986f79-0954-5657-a80a-22eec2033cf3$ml$::uuid, $ml$healthtech$ml$, 12, 3, $ml${"id": "healthtech-d12-c3", "title": "A hospital in a WISeR state", "lessonTitle": "AI decides prior authorization", "slot": 3, "type": "decide", "brief": {"headline": "You run revenue for a hospital in Ohio, one of six WISeR states. Some services for traditional Medicare patients now need prior approval reviewed with AI.", "kicker": "Decide: how do you prepare for AI prior authorization?", "fullText": "WISeR started January 1, 2026, in Arizona, New Jersey, Ohio, Oklahoma, Texas and Washington. Vendors earn more when spending falls, and a human clinician must review denials.\n\nYou can wait and see, or prepare documentation and track denials from day one.", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, "evidence": {"kind": "faceOff", "prompt": "Which plan protects your hospital better?", "left": {"name": "Prepare and track", "note": "Full records, denial tracking, appeals ready"}, "right": {"name": "Wait and see", "note": "Handle problems as they come"}, "correctIndex": 0, "explanation": "Complete records and tracking make it easier to get approvals and appeal denials."}, "numbers": {"kind": "numberSense", "prompt": "How many states are in the WISeR test?", "min": 0, "max": 15, "value": 6, "unit": "states", "explanation": "Six: Arizona, New Jersey, Ohio, Oklahoma, Texas and Washington."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CFO asks what to do first about WISeR.", "prompt": "What do you recommend?", "options": ["Track WISeR denials from day one", "Ignore it until revenue drops", "Stop treating Medicare patients"], "correctIndex": 0, "consequences": ["Data shows patterns and supports appeals.", "By then, cash is already lost.", "That harms patients and revenue."], "explanation": "Tracking denials early shows patterns and supports appeals."}, "proReasoning": "Revenue leaders measure a new rule from the first day.", "commonMistake": "Waiting for losses before acting.", "mentalModel": "Measure from day one."}, "invest": {"call": {"kind": "theCall", "situation": "You compare hospitals in WISeR and non-WISeR states.", "prompt": "What could differ?", "options": ["Their parking fees", "Denials and delays on some services", "The size of their hospital buildings"], "correctIndex": 1, "consequences": ["Parking is unrelated.", "WISeR adds review for some Medicare services.", "Size is unrelated to WISeR."], "explanation": "Hospitals in WISeR states may see more reviews and delays on some services."}, "proReasoning": "Investors check where a new rule applies.", "commonMistake": "Treating a state test as national.", "mentalModel": "Check where a rule applies."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could build tools for hospitals in WISeR states.", "prompt": "Which tool is most needed?", "options": ["A cafeteria menu app for all visitors", "A hospital parking app", "Prior authorization tracking and appeals"], "correctIndex": 2, "consequences": ["Menus do not affect approvals.", "Parking does not affect approvals.", "Hospitals face new reviews and possible denials."], "explanation": "New reviews create work tracking requests and appeals."}, "proReasoning": "Founders build for the work a new rule creates.", "commonMistake": "Building for problems the rule does not touch.", "mentalModel": "Build for the rule's new work."}, "curiosity": {"call": {"kind": "theCall", "situation": "A relative in Texas needs approval before a Medicare service.", "prompt": "Why might that be new?", "options": ["Texas is in the WISeR test", "Medicare ended in Texas", "A new state law bans the service"], "correctIndex": 0, "consequences": ["WISeR adds prior authorization in six states.", "Medicare continues in Texas.", "WISeR is a federal test."], "explanation": "WISeR added prior authorization for some services in six states, including Texas."}, "proReasoning": "Ask whether a new rule applies only in your state.", "commonMistake": "Assuming all of Medicare changed.", "mentalModel": "Some rules apply only in some states."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:e8d3fdf6e027$ml$]::text[]),
($ml$cc0bfc8c-c79d-501e-a1de-ac98761701bd$ml$::uuid, $ml$healthtech$ml$, 13, 1, $ml${"id": "healthtech-d13-c1", "title": "Six requests, one year", "lessonTitle": "Your right to your own records", "slot": 1, "type": "apply", "brief": {"headline": "On December 16, 2025, HHS settled with Concentra for $112,500. It was the 54th action under HHS's Right of Access Initiative.", "kicker": "Apply the right of access: how long is too long?", "fullText": "A patient asked Concentra for their records six times, starting in February 2018. They got access in March 2019, more than a year later.\n\nHIPAA generally gives a provider 30 days to respond to a records request. HHS's Office for Civil Rights runs the initiative and settles cases like this one.", "sources": [{"url": "https://www.hhs.gov/press-room/ocr-settles-with-concentra.html", "label": "HHS, OCR settles with Concentra"}]}, "evidence": {"kind": "buildChain", "prompt": "Put the Concentra case in order.", "steps": ["A patient requests records in February 2018", "The patient asks five more times", "The patient gets access in March 2019", "OCR investigates", "Concentra settles for $112,500"], "explanation": "A year of delay led to an OCR settlement."}, "numbers": {"kind": "numberSense", "prompt": "How many thousand dollars was the Concentra settlement?", "min": 0, "max": 250, "value": 112.5, "unit": "K", "explanation": "$112,500, the 54th right of access action."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You start as a privacy officer at a provider network.", "prompt": "What do you check first after Concentra?", "options": ["How many patients use the app", "How the waiting room looks", "How fast records requests are met"], "correctIndex": 2, "consequences": ["App use is not the legal test.", "Decor is not a privacy issue.", "Delays led to the $112,500 settlement."], "explanation": "Concentra was fined over a year of delay. Response time is the key check."}, "proReasoning": "Privacy officers measure the deadline regulators enforce.", "commonMistake": "Focusing on tools before deadlines.", "mentalModel": "Measure the deadline that is enforced."}, "invest": {"call": {"kind": "theCall", "situation": "You review a provider with many records complaints.", "prompt": "What risk does Concentra show?", "options": ["Enforcement for slow records access", "Lower demand for its care overall", "Higher drug prices"], "correctIndex": 0, "consequences": ["OCR has brought dozens of such actions.", "Complaints do not cut demand directly.", "Records access is unrelated to drugs."], "explanation": "OCR keeps settling right of access cases. Slow responses bring penalties."}, "proReasoning": "Investors read complaint patterns as early enforcement risk.", "commonMistake": "Treating records requests as a minor admin task.", "mentalModel": "Complaints are early warnings."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build software that tracks records requests.", "prompt": "What is your strongest pitch?", "options": ["Replace your doctors", "Never miss the 30-day deadline", "Collect more patient data"], "correctIndex": 1, "consequences": ["Your tool does admin work.", "Concentra paid for missing it badly.", "More data is not the goal here."], "explanation": "Providers pay penalties for slow access, so deadline tracking has clear value."}, "proReasoning": "Founders sell against a penalty buyers already fear.", "commonMistake": "Pitching features without the penalty they prevent.", "mentalModel": "Sell against a known penalty."}, "curiosity": {"call": {"kind": "theCall", "situation": "You asked a clinic for your records weeks ago.", "prompt": "What does HIPAA generally require?", "options": ["A response within 5 years", "No response at all", "A response within 30 days"], "correctIndex": 2, "consequences": ["Far too long under HIPAA.", "Patients have a right of access.", "HIPAA generally sets 30 days."], "explanation": "HIPAA generally gives providers 30 days to respond to records requests."}, "proReasoning": "You can file a complaint with OCR if a provider ignores you.", "commonMistake": "Thinking you must wait as long as the clinic wants.", "mentalModel": "You have a right to your records."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:314310a35686$ml$]::text[]),
($ml$9f9519bc-ee28-5a4e-8bd1-5ff58646b9d1$ml$::uuid, $ml$healthtech$ml$, 13, 2, $ml${"id": "healthtech-d13-c2", "title": "The right that comes with HIPAA", "lessonTitle": "Your right to your own records", "slot": 2, "type": "connect", "brief": {"headline": "Day 5 showed which organizations HIPAA covers. The same law gives patients the right to get their own records from them. By July 2022, OCR had brought 38 right of access actions.", "kicker": "Connect day 5 and day 13: covered entities owe patients access.", "fullText": "HIPAA covers providers, health plans and clearinghouses. Patients can request copies of their records from them.\n\nHHS's Office for Civil Rights investigates complaints. Settlements in a 2022 batch ranged from $3,500 for a small practice to $240,000 for a health system.", "sources": [{"url": "https://www.hhs.gov/hipaa/for-professionals/covered-entities/index.html", "label": "HHS, HIPAA covered entities"}, {"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 right of access cases"}]}, "evidence": {"kind": "sortSignal", "prompt": "Does each support or block a patient's access?", "buckets": ["Supports access", "Blocks access"], "items": [{"text": "Sending records when asked", "bucket": 0}, {"text": "Offering a patient portal", "bucket": 0}, {"text": "Ignoring a records request", "bucket": 1}, {"text": "Delaying for months", "bucket": 1}], "explanation": "Ignoring or delaying requests led to OCR enforcement."}, "numbers": {"kind": "numberSense", "prompt": "How many right of access actions had OCR brought by July 2022?", "min": 0, "max": 100, "value": 38, "unit": "actions", "explanation": "38 enforcement actions by July 2022."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a health plan. A member asks for their claims records.", "prompt": "What applies?", "options": ["HIPAA access rights, as a health plan", "No rule applies; plans can refuse", "Only the FTC app rule"], "correctIndex": 0, "consequences": ["Health plans are covered entities.", "Covered entities must give access.", "The FTC rule covers apps outside HIPAA."], "explanation": "Health plans are HIPAA covered entities, so members have access rights."}, "proReasoning": "Staff map their employer to HIPAA roles before answering.", "commonMistake": "Assuming access rights apply only to doctors.", "mentalModel": "Covered means access is owed."}, "invest": {"call": {"kind": "theCall", "situation": "A 2022 batch of settlements ranged from $3,500 to $240,000.", "prompt": "How do you read that range?", "options": ["Penalties only hit hospitals", "Penalties scale with the organization", "All penalties are identical in size"], "correctIndex": 1, "consequences": ["Small practices were fined too.", "Small practices paid less than health systems.", "Amounts varied widely."], "explanation": "Settlements ranged from small practices to health systems, scaled by size."}, "proReasoning": "Investors look at who gets fined, not just how much.", "commonMistake": "Assuming only big organizations face enforcement.", "mentalModel": "Small players get fined too."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your patient app gathers records from many providers.", "prompt": "Which right helps your users?", "options": ["The FTC breach rule", "No right applies", "HIPAA's right of access"], "correctIndex": 2, "consequences": ["That rule covers breaches by apps.", "Patients do have a right of access.", "Users can request their records from providers."], "explanation": "The right of access lets patients request their records, which your app can use."}, "proReasoning": "Founders build on rights users already hold.", "commonMistake": "Ignoring rights that help your users.", "mentalModel": "Build on rights users hold."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder if your insurer must share your records.", "prompt": "What is accurate?", "options": ["Yes, health plans are covered by HIPAA", "No, only doctors must share records", "Only if you pay a lawyer"], "correctIndex": 0, "consequences": ["Plans are covered entities.", "Plans and providers are both covered.", "No lawyer is needed to ask."], "explanation": "Health plans are HIPAA covered entities, so the right of access applies."}, "proReasoning": "Ask in writing and keep a copy of your request.", "commonMistake": "Thinking only doctors hold your records.", "mentalModel": "Insurers hold records too."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3e2b02f938d2$ml$]::text[]),
($ml$9b0153f8-b98b-5c96-9367-b4032f6eb53a$ml$::uuid, $ml$healthtech$ml$, 13, 3, $ml${"id": "healthtech-d13-c3", "title": "The records backlog", "lessonTitle": "Your right to your own records", "slot": 3, "type": "decide", "brief": {"headline": "You run a small medical practice. Records requests are piling up, and some are weeks old. OCR settlements have reached small practices too.", "kicker": "Decide: how do you clear the backlog?", "fullText": "HIPAA generally gives providers 30 days to respond. Settlements in a 2022 batch reached as low as $3,500 for a small practice.\n\nYou can let requests wait, hire help, or set up a tracked process with deadlines.", "sources": [{"url": "https://www.hhs.gov/press-room/ocr-settles-with-concentra.html", "label": "HHS, OCR settles with Concentra"}, {"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 right of access cases"}]}, "evidence": {"kind": "multipleChoice", "prompt": "What fixes the backlog for good?", "options": ["Answering only when patients complain", "Charging high fees to slow requests", "A tracked process with deadlines"], "correctIndex": 2, "explanation": "A tracked process meets the 30-day rule. Waiting for complaints invites enforcement."}, "numbers": {"kind": "numberSense", "prompt": "How many days does HIPAA generally allow to respond?", "min": 0, "max": 90, "value": 30, "unit": "days", "explanation": "Generally 30 days."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You are the practice manager. The doctor asks for a plan.", "prompt": "What do you do first?", "options": ["Delete old requests", "List requests by due date and clear them", "Wait for patients to call back again"], "correctIndex": 1, "consequences": ["Deleting requests breaks the rule.", "Oldest first meets the deadline.", "Repeat requests show delay, as in Concentra."], "explanation": "Clearing requests by due date keeps the practice inside the 30-day rule."}, "proReasoning": "Managers sort by deadline before adding people.", "commonMistake": "Waiting for repeat requests.", "mentalModel": "Sort by deadline."}, "invest": {"call": {"kind": "theCall", "situation": "You advise a group of small practices.", "prompt": "Where is a cheap fix with real value?", "options": ["New lobby furniture", "A bigger sign out front", "Records request tracking"], "correctIndex": 2, "consequences": ["Furniture does not reduce risk.", "Signs do not reduce risk.", "It prevents penalties and complaints."], "explanation": "A simple tracking process prevents enforcement."}, "proReasoning": "Advisers find cheap fixes for known risks.", "commonMistake": "Spending on looks over compliance.", "mentalModel": "Fix known risks cheaply."}, "build_startup": {"call": {"kind": "theCall", "situation": "You could sell a records request tool to small practices.", "prompt": "What price model fits?", "options": ["A low monthly fee", "A huge upfront license", "A share of patient revenue"], "correctIndex": 0, "consequences": ["Small practices have small budgets.", "Too costly for small practices.", "Odd for an admin tool."], "explanation": "Small practices need affordable tools to meet the 30-day rule."}, "proReasoning": "Founders price for the buyer's size.", "commonMistake": "Pricing small buyers like hospitals.", "mentalModel": "Price for the buyer's size."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your small clinic says it is \"too busy\" to send your records.", "prompt": "Does being small excuse it?", "options": ["Only if it is a busy month", "No, small practices have been fined", "Yes, small clinics are exempt"], "correctIndex": 1, "consequences": ["Busy months do not change the rule.", "A small practice paid $3,500 in 2022.", "Covered providers are not exempt by size."], "explanation": "HIPAA access rights apply regardless of practice size."}, "proReasoning": "Politely cite the 30-day rule in a written request.", "commonMistake": "Accepting \"too busy\" as a reason.", "mentalModel": "Size does not excuse delay."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:3c16828ca753$ml$]::text[]),
($ml$baac596c-a165-528b-bbbd-f061237a65a2$ml$::uuid, $ml$healthtech$ml$, 14, 1, $ml${"id": "healthtech-d14-c1", "title": "The $3 billion bill", "lessonTitle": "The costliest breaches", "slot": 1, "type": "apply", "brief": {"headline": "The Change Healthcare attack cost UnitedHealth $3.09 billion in 2024, or $2.60 per share. That included $2.2 billion for direct response and $867 million from business disruption.", "kicker": "Apply breach costs: what does one attack cost a giant?", "fullText": "UnitedHealth also lent $9.03 billion to providers whose payments were stalled, and $4.5 billion had been repaid. Revenue at Optum Insight, which includes Change Healthcare, fell 1%.\n\nThe average healthcare breach cost $7.42 million in 2025. Change shows how far one breach can exceed that.", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/cybersecurity/the-financial-toll-of-the-change-healthcare-hack-7-numbers/", "label": "Becker's, the financial toll of the Change Healthcare hack"}, {"url": "https://www.techtarget.com/healthtechsecurity/news/366628031/Healthcare-remains-costliest-industry-for-breaches-at-742M", "label": "TechTarget, healthcare remains costliest industry for breaches"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The attack cost UnitedHealth $3.09 billion in 2024.", "UnitedHealth lent providers $9.03 billion.", "Optum Insight revenue rose 10% after the attack."], "fakeIndex": 2, "explanation": "Optum Insight revenue fell 1%."}, "numbers": {"kind": "numberSense", "prompt": "How many billions did the attack cost UnitedHealth in 2024?", "min": 0, "max": 8, "value": 3.1, "unit": "B", "explanation": "$3.09 billion, or $2.60 per share."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You present breach risk to a company's board.", "prompt": "Which Change Healthcare cost do you highlight?", "options": ["Business disruption, not just cleanup", "Only the cost of buying new laptops", "Only the ransom"], "correctIndex": 0, "consequences": ["$867 million came from disruption.", "Hardware was a small part.", "Response and disruption were far larger."], "explanation": "Disruption cost $867 million on top of $2.2 billion in direct response."}, "proReasoning": "Security leaders show boards the cost of operations stopping.", "commonMistake": "Presenting breach cost as only an IT expense.", "mentalModel": "Disruption is part of the bill."}, "invest": {"call": {"kind": "theCall", "situation": "You see UnitedHealth lent $9.03 billion to providers.", "prompt": "How do you read that?", "options": ["A cost already written off", "Cash at risk until it is repaid", "Pure profit for UnitedHealth"], "correctIndex": 1, "consequences": ["Loans are expected to be repaid.", "$4.5 billion had been repaid at that point.", "Loans are not income."], "explanation": "Loans support providers but tie up cash until repaid."}, "proReasoning": "Investors track cash tied up after a crisis.", "commonMistake": "Ignoring cash outflows beyond the reported cost.", "mentalModel": "Track cash, not just costs."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your security startup sells to health systems.", "prompt": "Which number makes your case best?", "options": ["$1 billion in snack sales", "Zero breaches last year", "$3.09 billion from one attack"], "correctIndex": 2, "consequences": ["Unrelated to security.", "Untrue for health care.", "It shows the scale of what is at risk."], "explanation": "One attack cost UnitedHealth $3.09 billion in a year."}, "proReasoning": "Founders cite real costs buyers recognize.", "commonMistake": "Pitching with fear but no numbers.", "mentalModel": "Cite real costs."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder how much a big hack can cost a company.", "prompt": "What did Change Healthcare cost UnitedHealth in 2024?", "options": ["About $3.09 billion", "About $3 million", "About $3 trillion"], "correctIndex": 0, "consequences": ["Per its reported 2024 figures.", "Far too low.", "Far more than its whole revenue."], "explanation": "The attack cost UnitedHealth about $3.09 billion in 2024."}, "proReasoning": "Compare the cost to a typical breach to see the scale.", "commonMistake": "Guessing breach costs without a source.", "mentalModel": "One attack can cost billions."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8a2964b0a6b2$ml$]::text[]),
($ml$e53a3a13-2dbb-53f6-92d7-2b24625a243d$ml$::uuid, $ml$healthtech$ml$, 14, 2, $ml${"id": "healthtech-d14-c2", "title": "Big breach, slow detection", "lessonTitle": "The costliest breaches", "slot": 2, "type": "connect", "brief": {"headline": "Day 6 covered the Change Healthcare breach of about 192.7 million people. IBM found healthcare breaches took 279 days on average to identify and contain in 2025.", "kicker": "Connect day 6 and day 14: why health breaches cost the most.", "fullText": "Healthcare was the costliest industry for breaches for the 14th year in a row. The average cost was $7.42 million, down from $9.77 million, but still above the $4.44 million global average.\n\nHealth data is sensitive, and breaches take long to find and fix. Large breaches like Change show why the stakes are so high.", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, Change Healthcare hack affected 192.7 million"}, {"url": "https://www.techtarget.com/healthtechsecurity/news/366628031/Healthcare-remains-costliest-industry-for-breaches-at-742M", "label": "TechTarget, healthcare remains costliest industry for breaches"}]}, "evidence": {"kind": "faceOff", "prompt": "Which had the higher average breach cost in 2025?", "left": {"name": "Healthcare", "note": "$7.42 million on average"}, "right": {"name": "All industries", "note": "$4.44 million global average"}, "correctIndex": 0, "explanation": "Healthcare was the costliest industry for the 14th year in a row."}, "numbers": {"kind": "numberSense", "prompt": "How many days did healthcare breaches take to identify and contain?", "min": 0, "max": 400, "value": 279, "unit": "days", "explanation": "About 279 days in 2025."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You interview for a health security role.", "prompt": "Which goal do you set first?", "options": ["Publish fewer reports", "Find and contain breaches faster", "Buy more office printers and paper"], "correctIndex": 1, "consequences": ["Reporting is not the issue.", "279 days is a long time for attackers inside.", "Printers do not stop breaches."], "explanation": "Healthcare breaches took 279 days to find and contain. Speed cuts damage."}, "proReasoning": "Security candidates aim at the slowest step.", "commonMistake": "Focusing on tools without a time goal.", "mentalModel": "Speed cuts breach damage."}, "invest": {"call": {"kind": "theCall", "situation": "Healthcare breach costs fell to $7.42 million but stayed highest.", "prompt": "What does that mean for security spending?", "options": ["Health security is no longer needed", "Breaches stopped in health care", "Demand for health security stays strong"], "correctIndex": 2, "consequences": ["Costs remain far above average.", "Breaches continue.", "Health stays the costliest industry."], "explanation": "Health care remains the costliest industry for breaches, so demand for security holds."}, "proReasoning": "Investors look past one year's dip to the ranking.", "commonMistake": "Reading a cost dip as a solved problem.", "mentalModel": "A dip is not a fix."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build breach detection for hospitals.", "prompt": "What metric do you promise to improve?", "options": ["Days to identify and contain", "Number of staff emails", "Size of the IT team"], "correctIndex": 0, "consequences": ["279 days is the industry's weak spot.", "Email count is not a security result.", "Team size is not an outcome."], "explanation": "Shortening the 279 days lowers breach costs."}, "proReasoning": "Founders promise the metric buyers are judged on.", "commonMistake": "Promising activity instead of results.", "mentalModel": "Promise the metric that matters."}, "curiosity": {"call": {"kind": "theCall", "situation": "You wonder why health breaches cost more than others.", "prompt": "What is one key reason?", "options": ["Health data is never stolen", "Health data is sensitive and slow to secure", "Hospitals have no computers to attack"], "correctIndex": 1, "consequences": ["Health data is a top target.", "Breaches take 279 days to find and fix.", "Hospitals rely heavily on computers."], "explanation": "Sensitive data and slow detection make health breaches costly."}, "proReasoning": "Notice how long a breach went undetected in news stories.", "commonMistake": "Assuming all breaches cost the same.", "mentalModel": "Sensitive data, higher costs."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:78fe96ce13d9$ml$]::text[]),
($ml$f94b2cf4-a207-5f64-9758-8ad83afb0320$ml$::uuid, $ml$healthtech$ml$, 14, 3, $ml${"id": "healthtech-d14-c3", "title": "Where to spend the security budget", "lessonTitle": "The costliest breaches", "slot": 3, "type": "decide", "brief": {"headline": "You lead security at a regional hospital. Your budget covers one big project. Healthcare breaches cost $7.42 million on average and took 279 days to identify and contain.", "kicker": "Decide: what do you fund first?", "fullText": "Breaches that run longer cost more. Change Healthcare's attackers got in through a portal without multi-factor authentication.\n\nYou can fund faster detection and multi-factor login, a new website, or a bigger IT help desk.", "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366628031/Healthcare-remains-costliest-industry-for-breaches-at-742M", "label": "TechTarget, healthcare remains costliest industry for breaches"}, {"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, Change Healthcare hack affected 192.7 million"}]}, "evidence": {"kind": "buildChain", "prompt": "Order a typical breach, from entry to response.", "steps": ["An attacker gets in", "The breach goes unnoticed", "The breach is identified", "The breach is contained", "Affected people are notified"], "explanation": "The longer the gap between entry and identification, the more damage is done."}, "numbers": {"kind": "numberSense", "prompt": "How many millions did an average healthcare breach cost in 2025?", "min": 0, "max": 12, "value": 7.4, "unit": "M", "explanation": "$7.42 million, down from $9.77 million."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CEO asks which project gives the most protection.", "prompt": "What do you recommend?", "options": ["A new website design for patients", "A bigger IT help desk", "Faster detection and multi-factor login"], "correctIndex": 2, "consequences": ["Design does not stop breaches.", "Help desks fix laptops, not breaches.", "It closes the Change gap and cuts dwell time."], "explanation": "Multi-factor login blocks a common entry, and faster detection cuts damage."}, "proReasoning": "Security leaders fund the controls tied to real breaches.", "commonMistake": "Funding visible projects over protective ones.", "mentalModel": "Fund what stops real breaches."}, "invest": {"call": {"kind": "theCall", "situation": "You rate a hospital's bonds. It lacks multi-factor login.", "prompt": "How do you treat that?", "options": ["As a higher breach and cash risk", "As irrelevant to its finances", "As a sign of strong security"], "correctIndex": 0, "consequences": ["Breaches cost millions and stall revenue.", "Breaches hit finances hard.", "Missing MFA is a weakness."], "explanation": "Missing multi-factor login raises breach risk, which can hit revenue."}, "proReasoning": "Investors treat basic security gaps as financial risk.", "commonMistake": "Ignoring cyber risk in hospital credit.", "mentalModel": "Security gaps are credit risk."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell multi-factor login to hospitals.", "prompt": "Which story makes your case?", "options": ["MFA is a fashion trend", "Change Healthcare's portal had no MFA", "Hospitals love trying out new apps"], "correctIndex": 1, "consequences": ["MFA is a basic control.", "It shows the real cost of skipping MFA.", "Liking apps is not a reason."], "explanation": "Change Healthcare's breached portal lacked multi-factor authentication."}, "proReasoning": "Founders tie their product to a real failure.", "commonMistake": "Selling a control without a real case.", "mentalModel": "Tie the product to a real failure."}, "curiosity": {"call": {"kind": "theCall", "situation": "Your hospital asks you to set up multi-factor login.", "prompt": "Why does it matter?", "options": ["It makes the hospital website prettier", "It is only for banks", "It blocks a common way attackers get in"], "correctIndex": 2, "consequences": ["It is a security step, not design.", "Health care uses it too.", "The Change breach came through a portal without it."], "explanation": "Multi-factor login adds a step that stops many stolen-password attacks."}, "proReasoning": "Turn on multi-factor login for health accounts.", "commonMistake": "Thinking passwords alone are enough.", "mentalModel": "One extra step stops many attacks."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:0dfb8926e06b$ml$]::text[]),
($ml$59d7a6da-f562-5189-97e7-6ad517e45d31$ml$::uuid, $ml$healthtech$ml$, 15, 1, $ml${"id": "healthtech-d15-c1", "title": "The Supreme Court backs HHS", "lessonTitle": "Hospitals beat HHS in court", "slot": 1, "type": "apply", "brief": {"headline": "On June 27, 2025, the Supreme Court ruled 6-3 in Kennedy v. Braidwood that the panel behind free preventive care under the ACA is constitutional.", "kicker": "Apply the court lesson: when does HHS authority hold up?", "fullText": "The US Preventive Services Task Force recommends which preventive services insurers must cover without cost sharing. The Court said its structure is valid because the HHS Secretary can remove members at will and review their recommendations.\n\nAbout 100 million privately insured people get preventive services without cost sharing. Unlike the 2024 tracking case, where a court limited HHS, this ruling kept HHS authority in place.", "sources": [{"url": "https://www.kff.org/affordable-care-act/kennedy-v-braidwood-the-supreme-court-upheld-aca-preventive-services-but-thats-not-the-end-of-the-story/", "label": "KFF, Kennedy v. Braidwood"}]}, "evidence": {"kind": "spotFake", "prompt": "One of these is false. Tap it.", "statements": ["The Court ruled 6-3 in the Braidwood case.", "The Court struck down the task force.", "The HHS Secretary can remove task force members at will."], "fakeIndex": 1, "explanation": "The Court upheld the task force structure as constitutional."}, "numbers": {"kind": "numberSense", "prompt": "About how many million privately insured people get preventive care without cost sharing?", "min": 0, "max": 250, "value": 100, "unit": "M", "explanation": "About 100 million, per KFF."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You work in policy at an insurer after Braidwood.", "prompt": "What does the ruling mean for your plans?", "options": ["All cost sharing is banned", "Preventive coverage rules stay in place", "Preventive coverage is now optional"], "correctIndex": 1, "consequences": ["It covers preventive services only.", "The task force structure was upheld.", "The ruling kept the coverage rules."], "explanation": "The Court upheld the task force, so preventive coverage rules remain."}, "proReasoning": "Policy staff read what a ruling keeps, not just what it changes.", "commonMistake": "Assuming every court case weakens a rule.", "mentalModel": "Read what a ruling keeps."}, "invest": {"call": {"kind": "theCall", "situation": "You cover insurers. Braidwood was decided 6-3.", "prompt": "Why does HHS control over the panel matter?", "options": ["HHS lost all power over the panel", "The panel now sets prices", "HHS can now shape coverage rules"], "correctIndex": 2, "consequences": ["The ruling rests on HHS control.", "The panel recommends services, not prices.", "The Secretary can remove members and review advice."], "explanation": "The ruling rests on the Secretary's control, so HHS can shape future recommendations."}, "proReasoning": "Investors watch who controls a rule after a ruling.", "commonMistake": "Ignoring who holds power after a case.", "mentalModel": "Watch who holds control."}, "build_startup": {"call": {"kind": "theCall", "situation": "Your startup offers preventive screenings through employers.", "prompt": "What does Braidwood mean for you?", "options": ["Coverage without cost sharing continues", "Employers must stop covering screenings", "Screenings are banned"], "correctIndex": 0, "consequences": ["About 100 million people keep this coverage.", "The ruling kept coverage rules.", "Nothing was banned."], "explanation": "Preventive coverage rules stay in place for private plans."}, "proReasoning": "Founders check how a ruling affects their buyer's duties.", "commonMistake": "Panicking at headlines before reading the ruling.", "mentalModel": "Read the ruling, not the headline."}, "curiosity": {"call": {"kind": "theCall", "situation": "You get a free preventive screening through your plan.", "prompt": "What did the 2025 ruling do to that?", "options": ["It made all care free", "It kept the coverage rule in place", "It ended free preventive care"], "correctIndex": 1, "consequences": ["It applies to preventive services.", "The Court upheld the task force.", "Coverage continues."], "explanation": "The Supreme Court upheld the structure behind free preventive care."}, "proReasoning": "Check your plan's preventive benefits each year.", "commonMistake": "Assuming a big case always removes benefits.", "mentalModel": "Some rulings keep benefits."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:89229702738d$ml$]::text[]),
($ml$c9398bbe-a743-53f9-8418-84a676ffe5ed$ml$::uuid, $ml$healthtech$ml$, 15, 2, $ml${"id": "healthtech-d15-c2", "title": "Trackers and the limits of HIPAA", "lessonTitle": "Hospitals beat HHS in court", "slot": 2, "type": "connect", "brief": {"headline": "Day 5 showed the FTC fining GoodRx for sharing health data with advertisers. In June 2024, a Texas judge vacated HHS guidance that limited hospitals' use of tracking tools on their websites.", "kicker": "Connect day 5 and day 15: who polices tracking depends on who you are.", "fullText": "Tracking pixels record what visitors do on a website and send it to third parties. The judge said HHS went beyond what HIPAA allows. HHS appealed, then dropped its appeal.\n\nHospitals are HIPAA covered entities, so the ruling limited HHS's reach over their websites. Apps like GoodRx fall under the FTC, which acted on its own rule.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in web tracker case"}, {"url": "https://www.arnoldporter.com/en/perspectives/blogs/enforcement-edge/2023/02/ftc-fines-goodrx", "label": "Arnold & Porter, FTC fines GoodRx $1.5 million"}, {"url": "https://www.hhs.gov/hipaa/for-professionals/covered-entities/index.html", "label": "HHS, HIPAA covered entities"}]}, "evidence": {"kind": "multipleChoice", "prompt": "Why did the judge vacate the HHS tracking guidance?", "options": ["Hospitals stopped using trackers", "The FTC asked the court to", "HHS went beyond what HIPAA allows"], "correctIndex": 2, "explanation": "The judge found the guidance was in clear excess of HHS's authority."}, "numbers": {"kind": "numberSense", "prompt": "How many millions of dollars did the FTC fine GoodRx?", "min": 0, "max": 10, "value": 1.5, "unit": "M", "explanation": "$1.5 million, under the Health Breach Notification Rule."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "You join a hospital's digital team in 2026.", "prompt": "What does the ruling change for trackers?", "options": ["It made all trackers illegal at once", "It made trackers required", "It removed one HHS basis for limits"], "correctIndex": 2, "consequences": ["The ruling did the opposite.", "Nothing requires trackers.", "The guidance was vacated and the appeal dropped."], "explanation": "The vacated guidance no longer restricts hospitals the same way, but other laws may apply."}, "proReasoning": "Digital teams know which rule fell and which still stand.", "commonMistake": "Reading one ruling as total freedom.", "mentalModel": "One rule falling is not all rules."}, "invest": {"call": {"kind": "theCall", "situation": "You compare a hospital and a health app, both using trackers.", "prompt": "Which regulator matters for each?", "options": ["HHS for the hospital, FTC for the app", "The FTC for both of these companies", "No regulator for either"], "correctIndex": 0, "consequences": ["Covered entities fall under HIPAA; apps under the FTC.", "Hospitals are HIPAA covered entities.", "GoodRx shows the FTC acts on apps."], "explanation": "Hospitals answer to HIPAA rules; apps answer to the FTC."}, "proReasoning": "Investors map each company to its regulator.", "commonMistake": "Assuming one regulator covers all health data.", "mentalModel": "Map each company to its regulator."}, "build_startup": {"call": {"kind": "theCall", "situation": "You build a health app with analytics.", "prompt": "Does the hospital ruling protect you?", "options": ["Yes, apps are covered by HIPAA", "No, apps fall under the FTC rule", "Yes, it frees all health trackers"], "correctIndex": 1, "consequences": ["Most apps are outside HIPAA.", "GoodRx was fined under the FTC rule.", "The ruling was about HHS guidance."], "explanation": "The ruling limited HHS, not the FTC. Apps still face the FTC rule."}, "proReasoning": "Founders check which regulator a ruling actually binds.", "commonMistake": "Applying a hospital ruling to an app.", "mentalModel": "Check which regulator a ruling binds."}, "curiosity": {"call": {"kind": "theCall", "situation": "You visit a hospital website and wonder about trackers.", "prompt": "What did the 2024 ruling do?", "options": ["Banned trackers on all health websites", "Required hospitals to sell data", "Vacated HHS limits on hospital trackers"], "correctIndex": 2, "consequences": ["No ban was issued.", "No such requirement exists.", "The judge said HHS exceeded its authority."], "explanation": "A judge vacated HHS guidance that restricted hospitals' use of trackers."}, "proReasoning": "Check a site's privacy settings when you browse health pages.", "commonMistake": "Assuming every health site is under the same rule.", "mentalModel": "Different sites, different rules."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:8db714f01bca$ml$]::text[]),
($ml$43e38147-f1fc-5075-b0ef-eff719eef64b$ml$::uuid, $ml$healthtech$ml$, 15, 3, $ml${"id": "healthtech-d15-c3", "title": "Keep the trackers?", "lessonTitle": "Hospitals beat HHS in court", "slot": 3, "type": "decide", "brief": {"headline": "You run the website for a hospital system. The HHS tracking guidance was vacated and HHS dropped its appeal. Your marketing team wants trackers back on.", "kicker": "Decide: do you turn the trackers back on?", "fullText": "The guidance had fueled class actions against hospitals, and the ruling removed a federal basis for them. But patients still care about privacy, and state laws may still apply.\n\nHealthcare breaches already cost more than in any other industry. Your choice affects trust and legal risk.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in web tracker case"}, {"url": "https://www.techtarget.com/healthtechsecurity/news/366628031/Healthcare-remains-costliest-industry-for-breaches-at-742M", "label": "TechTarget, healthcare remains costliest industry for breaches"}]}, "evidence": {"kind": "faceOff", "prompt": "Which approach carries less risk?", "left": {"name": "Limited trackers", "note": "Kept off pages about conditions and care"}, "right": {"name": "Trackers everywhere", "note": "On every page, including patient portals"}, "correctIndex": 0, "explanation": "Keeping trackers off sensitive pages lowers privacy and legal risk."}, "numbers": {"kind": "numberSense", "prompt": "How many millions was the global average breach cost in 2025?", "min": 0, "max": 10, "value": 4.4, "unit": "M", "explanation": "$4.44 million globally, against $7.42 million in healthcare."}, "calls": {"career": {"call": {"kind": "theCall", "situation": "Your CMO says the ruling means trackers are fine everywhere.", "prompt": "What do you say?", "options": ["Keep them off sensitive pages", "Put them on every page now", "Remove the whole website"], "correctIndex": 0, "consequences": ["Limits protect trust and reduce legal risk.", "State laws and trust still matter.", "The site serves patients."], "explanation": "The ruling removed one federal basis, not all risk."}, "proReasoning": "Web leaders weigh trust and other laws after a ruling.", "commonMistake": "Treating a ruling as permission for everything.", "mentalModel": "Less risk is not no risk."}, "invest": {"call": {"kind": "theCall", "situation": "A hospital puts trackers back on all pages after the ruling.", "prompt": "What risk remains?", "options": ["Higher drug prices", "State claims and lost patient trust", "None; the ruling ended all risk"], "correctIndex": 1, "consequences": ["Trackers do not affect drug prices.", "Other laws and trust still apply.", "Only one federal basis was removed."], "explanation": "The ruling removed a federal basis, but state laws and trust remain."}, "proReasoning": "Investors look for risk that a ruling did not touch.", "commonMistake": "Assuming a court win removes all exposure.", "mentalModel": "Look for risk a ruling missed."}, "build_startup": {"call": {"kind": "theCall", "situation": "You sell privacy tools for hospital websites.", "prompt": "How do you pitch after the ruling?", "options": ["Hospitals no longer need privacy", "Trackers are now illegal", "Protect trust and state law compliance"], "correctIndex": 2, "consequences": ["Privacy still matters to patients.", "The ruling did not ban trackers.", "These needs remain after the ruling."], "explanation": "The ruling narrowed federal limits, but trust and state rules remain."}, "proReasoning": "Founders reframe the pitch when one rule falls.", "commonMistake": "Selling only against a rule that no longer applies.", "mentalModel": "Reframe when a rule falls."}, "curiosity": {"call": {"kind": "theCall", "situation": "You notice ads after visiting a hospital page.", "prompt": "Why could that happen?", "options": ["A tracker may have shared your visit", "Your doctor sent your file to advertisers", "Ads read your mind"], "correctIndex": 0, "consequences": ["Trackers send visitor activity to third parties.", "That is not how web trackers work.", "Trackers explain it."], "explanation": "Tracking pixels record what visitors do and send it to third parties."}, "proReasoning": "Use browser privacy settings on health sites.", "commonMistake": "Assuming health sites never track you.", "mentalModel": "Health sites can track visits."}}}$ml$::jsonb, ARRAY[$ml$handwritten-v1$ml$, $ml$src:c18f24beba50$ml$]::text[])
